    ["02-10"] = {steps={[1]={npc="维兹班恩·曲针", tgt="维兹班恩·曲针"}, [2]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [3]={node="奥伯丁"}, [4]={hint="收集6只蟹腿，把它们放进传声盒827号。", desc="沿奥伯丁南边海岸打9-10级的小潮行蟹收集蟹腿。如果还没接搁浅的巨兽，满11级后下次路过码头时再接。"}, [5]={hint="从奥伯丁南面的海岸上收集海洋生物的骨头，然后带着骨头向奥伯丁的温尼斯·布莱葛回复。"}, [6]={npc="传声盒827号", npcObj=true}, [7]={npc="传声盒827号", npcObj=true}, [8]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [9]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [10]={hint="将艾鲁拉的徽章和8块月神矿石交给达纳苏斯的艾兰娜瑞。"}, [11]={npc="塞瑞利恩·白爪", tgt="塞瑞利恩·白爪"}, [12]={hint="在奥伯丁西面海水中的海龟骸骨那里取回海龟残骸，然后与奥伯丁的温尼斯·布莱葛谈一谈。"}, [13]={hint="从位于传声盒411号附近的深海中收集3颗黑海岸蛇颈龙的眼球。"}, [14]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [15]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [16]={npc="萨纳瑞恩·绿树", tgt="萨纳瑞恩·绿树"}, [17]={npc="特伦希斯", tgt="特伦希斯"}, [18]={hint="活捉一只狂暴蓟熊，把它带到萨纳瑞恩那里。"}, [19]={hint="使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。"}, [20]={npc="阿斯特利安", tgt="阿斯特利安"}, [21]={npc="阿斯特利安", tgt="阿斯特利安"}, [22]={hint="帮巴莎兰的阿斯特利安收集8只劣魔耳环。"}, [23]={npc="阿斯特利安", tgt="阿斯特利安"}, [24]={npc="阿斯特利安", tgt="阿斯特利安"}, [25]={hint="获取远古月亮石封印，把它交给巴莎兰的阿斯特利安。"}, [26]={npc="阿斯特利安", tgt="阿斯特利安"}, [27]={npc="阿斯特利安", tgt="阿斯特利安"}, [28]={npc="萨纳瑞恩·绿树", tgt="萨纳瑞恩·绿树"}, [29]={npc="萨纳瑞恩·绿树", tgt="萨纳瑞恩·绿树"}, [30]={npc="哨兵戈琳达·纳希恩", tgt="哨兵戈琳达·纳希恩"}, [31]={npc="巴瑞萨斯·月影", tgt="巴瑞萨斯·月影"}, [32]={npc="通缉：莫克迪普！", npcObj=true}, [33]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [34]={hint="到奥伯丁的东边去，沿着黑海岸东部边界的山脉寻找一颗巨大的红色水晶，然后向奥伯丁的哨兵戈琳达·纳希恩汇报你的发现。"}, [35]={npc="哨兵坦莎·月刃", tgt="哨兵坦莎·月刃"}, [36]={hint="研究刻有亚米萨兰的故事及其被毁经过的石碑，然后回到黑海岸的哨兵坦莎·月刃那里。"}, [37]={hint="释放安娜雅·晨路的灵魂，把她的坠饰交给奥伯丁的塞瑞利恩·白爪。"}, [38]={hint="帮奥伯丁的桑迪斯·织风取回7个上层精灵的遗物。"}, [39]={hint="用亚米萨兰废墟中的远古火焰摧毁远古月亮石封印，然后回到巴莎兰的阿斯特利安那里。"}, [40]={hint="找到并消灭那只名叫贾伊瓦内尔的猫头鹰，然后拔下它的一根羽毛。最后一次有人瞧见这只黑色猫头鹰，还是在亚米萨兰废墟北边的山脚底下。拿着羽毛，去向奥伯丁的哨兵戈琳达·纳希恩报告贾伊瓦内尔的死讯。"}, [41]={npc="哨兵坦莎·月刃", tgt="哨兵坦莎·月刃"}, [42]={npc="搁浅的海龟", npcObj=true, desc="往南多打狂暴蓟熊，再到 38, 60 一带找，打到 6-10 只先停。"}, [43]={hint="在黑海岸找到一处堕落熊怪的营地，然后向奥伯丁的特伦希斯报告。"}, [44]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [45]={npc="塞瑞利恩·白爪", tgt="塞瑞利恩·白爪"}, [46]={npc="哨兵戈琳达·纳希恩", tgt="