    ["02-13"] = {steps={[1]={npc="古博·布拉普", tgt="古博·布拉普"}, [2]={npc="通缉：莫克迪普！", npcObj=true}, [3]={npc="考古学家霍莉", tgt="考古学家霍莉"}, [4]={npc="考古学家霍莉", tgt="考古学家霍莉"}, [5]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [6]={npc="高尔博德·钢手", tgt="高尔博德·钢手"}, [7]={npc="高尔博德·钢手", tgt="高尔博德·钢手"}, [8]={npc="戈沙拉·夜语", tgt="戈沙拉·夜语"}, [9]={npc="特伦希斯", tgt="特伦希斯"}, [10]={npc="特伦希斯", tgt="特伦希斯"}, [11]={npc="神秘的红色水晶", npcObj=true}, [12]={npc="神秘的红色水晶", npcObj=true}, [13]={npc="阿斯特利安", tgt="阿斯特利安"}, [14]={npc="搁浅的海洋生物", npcObj=true}, [15]={hint="为奥伯丁的高尔博德·钢手找回银色清晨号和迷雾之纱号的保险箱。两只箱子都在村庄北面的沉船残骸中。"}, [16]={npc="传声盒411号", npcObj=true}, [17]={npc="传声盒411号", npcObj=true}, [18]={npc="搁浅的海龟", npcObj=true}, [19]={text="从这里跳进河里，游到瀑布下的水潭。接下来沿路见到月夜猛虎幼崽和狂暴蓟熊就打。"}, [20]={hint="到奥伯丁的北面去，沿着壁泉河到达第一个瀑布处，从瀑布下的水潭中取出一份水样。"}, [21]={hint="收集6块优质蟹肉，把它们交给奥伯丁的古博·布拉普。"}, [22]={npc="搁浅的海龟", npcObj=true}, [23]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [24]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [25]={hint="在奥萨拉克斯之塔附近帮巴苏尔·影击收集4块破旧的羊皮纸。"}, [26]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [27]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [28]={hint="到森林里去杀掉20头狂暴蓟熊。"}, [29]={hint="收集6颗月夜猛虎的牙齿，把它们放进传声盒323号。"}, [30]={hint="收集5个粗柄蘑菇和1个毒帽蘑菇，把它们交给奥伯丁的巴瑞萨斯·月影。"}, [31]={npc="传声盒323号", npcObj=true}, [32]={npc="传声盒323号", npcObj=true}, [33]={npc="萨纳瑞恩·绿树", tgt="萨纳瑞恩·绿树"}, [34]={npc="萨纳瑞恩·绿树", tgt="萨纳瑞恩·绿树"}, [35]={npc="高尔博德·钢手", tgt="高尔博德·钢手"}, [36]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [37]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [38]={npc="哨兵戈琳达·纳希恩", tgt="哨兵戈琳达·纳希恩"}, [39]={npc="巴瑞萨斯·月影", tgt="巴瑞萨斯·月影", desc="到月亮井把空的净化碗装满。"}, [40]={npc="巴瑞萨斯·月影", tgt="巴瑞萨斯·月影"}, [41]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [42]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [43]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [44]={npc="古博·布拉普", tgt="古博·布拉普"}, [45]={npc="搁浅的海洋生物", npcObj=true}, [46]={npc="搁浅的海洋生物", npcObj=true, desc="靠近营火才会触发事件，现在打或晚点路线再经过时打都行。"}, [47]={npc="搁浅的海龟", npcObj=true}, [48]={npc="搁浅的海龟", npcObj=true}, [49]={npc="搁浅的海洋生物", npcObj=true}, [50]={npc="哨兵阿娜莎", tgt="哨兵阿娜莎", desc="往下一个任务途中，看到月夜雄虎就打（幼崽和族母会一起拉）。"}, [51]={hint="保护哨兵阿娜莎，然后向灰谷迈斯特拉岗哨的奥奈雅报告。"}, [52]={npc="安努", tgt="安努"}, [53]={npc="安努", tgt="安努"}, [54]={npc="占卜之碗", npcObj=true, desc="走到 39.2, 86.9，使用安努给的小瓶放在地上。"}, [55]={npc="占卜之碗", npcObj=true}, [56]={npc="暮光之书", npcObj=true}, [57]={npc="暮光之书", npcObj=true}, [58]={npc="暮光之书", npcObj=true}, [59]={hint="从黑海岸主宰之剑的暮光信徒或暮光暴徒身上夺取一颗无双之眼，然后在奥伯丁里找到那个愿意接手这烫手山芋的人。"}, [60]={npc="瑟瑞露尼", tgt="瑟瑞露尼", desc="护送任务：组队时等大家进度一致再接，并关掉自动接交。"}, [61]={hint="帮助瑟瑞露尼逃跑，然后告诉在艾森娜神殿的瑟瑞希尔，她的妹妹目前很安全。"}, [62]={npc="深渊之神", npcObj=true, tag="可选", desc="右键背包里的《深渊之神》接任务。；坑里的怪低几率掉《深渊之神》，有掉才接。"}, [63]={npc="勘察员雷姆塔维尔", tgt="勘察员雷姆塔维尔", desc="护送任务：组队时等大家进度一致再接，并关掉自动接交。；让勘察员雷姆塔维尔先跑，只打先攻击他的怪。"}, [64]={npc="勘察员雷姆塔维尔", tgt="勘察员雷姆塔维尔"}, [65]={hint="在勘察员雷姆塔维尔搜寻神秘化石的时候保护他，然后回到奥伯丁的考古学家霍莉那里。"}, [66]={hint="收集4块灰色头皮，然后把它们放在传声盒525号中。"}, [67]={npc="传声盒525号", npcObj=true}, [68]={hint="收集5张优质月夜猛虎毛皮，把它们交给奥伯丁的特伦希斯。"}, [69]={npc="安努", tgt="安努"}, [70]={npc="安努", tgt="安努"}, [71]={npc="阿尔巴尔", tgt="阿尔巴尔"}, [72]={hint="找到并杀死名为莫克迪普的鱼人。它守护着位于奥伯丁南部海岸的鱼人营地。", desc="会来好几波鱼人，每波 2-3 只；每波最后一只拉离营火再杀，吃喝完再拉下一波，或找队伍。"}, [73]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [74]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [75]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [76]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [77]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [78]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [79]={npc="哨兵戈琳达·纳希恩", tgt="哨兵戈琳达·纳希恩"}, [80]={npc="考古学家霍莉", tgt="考古学家霍莉"}, [81]={npc="考古学家霍莉", tgt="考古学家霍莉"}, [82]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [83]={npc="特伦希斯", tgt="特伦希斯"}, [84]={npc="特伦希斯", tgt="特伦希斯"}, [85]={to="Rut'theran Village", toA="{a:702}", from="奥伯丁"}, [86]={to="Rut'theran Village", toA="{a:702}"}, [87]={npc="尼莎·影歌", tgt="尼莎·影歌"}, [88]={text="走进鲁瑟兰村的传送门到达纳苏斯。"}, [89]={npc="首席考古学家杜瑟·灰须", tgt="首席考古学家杜瑟·灰须"}, [90]={npc="首席考古学家杜瑟·灰须", tgt="首席考古学家杜瑟·灰须"}, [91]={npc="艾兰娜瑞", tgt="艾兰娜瑞"}, [92]={npc="艾兰娜瑞", tgt="艾兰娜瑞"}, [93]={npc="玛希尔", tgt="玛希尔"}, [94]={npc="玛希尔", tgt="玛希尔", desc="奖励月神武器。"}, [95]={npc="玛希尔", tgt="玛希尔", desc="奖励月神武器。"}, [96]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者", desc="在奥伯丁的月夜枭兽之石完成身心之力后，回达纳苏斯交，学熊形态。"}, [97]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者", tag="可以先在拍卖行买（或请小号寄来）5 株地根草（之后的收集解药用）。"}, [98]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [99]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [100]={hint="使用空的峭壁之泉取样器在瀑布洞口获得水样。", desc="从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，再飞奥伯丁。"}, [101]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌"}, [102]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌", desc="在黑海岸采地根草和月亮菇，回奥伯丁交。地根草 ×5 可以在拍卖行买。"}, [103]={hint="收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。", desc="在黑海岸采地根草和月亮菇，回奥伯丁交。"}, [104]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌", desc="在黑海岸采地根草和月亮菇，回奥伯丁交。"}, [105]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌", desc="用解药治疗黑海岸生病的鹿。"}, [106]={hint="对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。", desc="用解药治疗黑海岸生病的鹿。"}, [107]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="治好 10 头鹿后用传送：月光林地回去交。"}, [108]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="交任务学解毒术。"}, [109]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者", desc="交任务学解毒术。从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，走村内传送门进达纳苏斯。"}, [110]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者"}, [111]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [112]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="在月神湖底找到神殿灵珠。"}, [113]={hint="在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。", desc="在月神湖底找到神殿灵珠。"}, [114]={npc="塔加里", tgt="塔加里", desc="在月神湖底找到神殿灵珠。"}, [115]={npc="塔加里", tgt="塔加里", desc="两个奇怪的保险箱各装半块坠饰，一个在黑海岸奥伯丁北方的海底，一个在西部荒野西北海岸外的海底。"}, [116]={hint="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。", desc="从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，飞奥伯丁，往北游到海底的带锁箱；再从奥伯丁搭船到暴风城，飞哨兵岭，往西北到海岸外游下去开另一个带锁箱。"}, [117]={text="集齐两半后用传送：月光林地回去，在雷姆洛斯神殿附近把坠饰合成一个。"}, [118]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [119]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="交任务学水栖形态。"}, [120]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者", desc="交任务学水栖形态。从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，走村内传送门进达纳苏斯。"}, [121]={text="走进达纳苏斯的传送门回鲁瑟兰村。"}, [122]={nodeA="{a:702}", node="Rut'theran Village"}, [123]={to="奥伯丁"}, [124]={hint="找到雌蓟熊，然后杀掉它。"}, [125]={hint="在空的净化碗里盛满奥伯丁月亮井的井水。"}, [126]={hint="收集6个黑暗深渊遗物，把它们交给古树之林的安努。"}, [127]={hint="替古树之林的阿尔巴尔消灭12名雷鳞侍从、8名雷鳞巫师和6名雷鳞战士。"}, [128]={hint="找到一名雷鳞兽王，除掉她，并带回她的深渊统御法杖。"}, [129]={}}},
    ["05-d2"] = {name="洛丹伦废墟", entrance="幽暗城 72.41, 11.37", steps={[1]={text="远程选做：入口在幽暗城上方的洛丹伦废墟，要穿过部落地区。从奥伯丁乘船先到米奈希尔港，再循北线到南海镇下船并开飞行点，往北经希尔斯布莱德丘陵、银松森林走到提瑞斯法林地；出本后用炉石回暴风城，接回 「{s:02-14}」。", tag="可选"}, [2]={text="洛丹伦废墟 入口"}, [3]={}, [4]={npc="血污徽章", npcObj=true, tag="掉落才接、可选", desc="右键背包里的血污徽章接任务。"}, [5]={hint="收集10枚血污徽章，并把它们交给暴风城的马库斯·乔纳森将军。", tag="可选"}, [6]={npc="洛丹伦纹章", npcObj=true, desc="右键背包里的洛丹伦纹章接任务。"}, [7]={npc="Blood-Stained Parchment", npcObj=true, desc="右键背包里的 Blood-Stained Parchment 接任务。"}, [8]={}, [9]={npc="孤儿监护员奈丁加尔", tgt="孤儿监护员奈丁加尔"}, [10]={npc="德娜·肯尼迪", tgt="德娜·肯尼迪"}, [11]={npc="马库斯·乔纳森将军", tgt="马库斯·乔纳森将军", tag="可选"}}},
    ["02-14"] = {grind={[1]={mob="赤脊山猛击者", note="湖畔镇北边的豺狼人营地，普通怪，离飞行点近。"}, [2]={mob="黑石前锋", note="止水湖东北岸的黑石兽人，等级较合适，混有步兵，从外围拉。"}}, steps={[1]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [2]={npc="高阶牧师劳瑞娜", tgt="高阶牧师劳瑞娜", desc="暴风城接，到铁炉堡交，学防护恐惧结界。"}, [3]={npc="高阶牧师洛汉", tgt="高阶牧师洛汉", desc="暴风城接，到铁炉堡交，学防护恐惧结界。"}, [4]={text="在铁炉堡搭矿道地铁回暴风城。"}, [5]={npc="高阶牧师劳瑞娜", tgt="高阶牧师劳瑞娜", desc="暴风城接，到丹莫罗交。"}, [6]={npc="高阶女祭司米姆斯", tgt="高阶女祭司米姆斯", desc="暴风城接，到丹莫罗交。"}, [7]={text="回铁炉堡搭矿道地铁到暴风城。"}, [8]={npc="詹妮亚·坎农", tgt="詹妮亚·坎农", desc="蓝色隐士酒吧在暴风城法师区。"}, [9]={componentNpc="裂隙怒灵", hint="到暴风城法师区的蓝色隐士旅店使用卷轴。打到裂隙怒灵昏迷，用封灵箱捕捉，再拾取地上的满箱，共需三个。", desc="蓝色隐士酒吧在暴风城法师区。"}, [10]={npc="詹妮亚·坎农", tgt="詹妮亚·坎农", desc="蓝色隐士酒吧在暴风城法师区。"}, [11]={npc="詹妮亚·坎农", tgt="詹妮亚·坎农", desc="需要亚麻布 ×10和充能裂隙宝石 ×6。若顺路回洛克莫丹，可从银泉矿洞北口（约35.9,18.2）进洞开矿工的箱子。缺材料先走主线，任务日志显示可交时再到暴风城找裁缝。"}, [12]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="需要亚麻布 ×10和充能裂隙宝石 ×6。若顺路回洛克莫丹，可从银泉矿洞北口（约35.9,18.2）进洞开矿工的箱子。缺材料先走主线，任务日志显示可交时再到暴风城找裁缝。"}, [13]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="奖励法纹长袍。"}, [14]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="奖励法纹长袍。"}, [15]={npc="黑暗缚灵者加科因", tgt="黑暗缚灵者加科因"}, [16]={npc="先知塔卡尔", tgt="先知塔卡尔", desc="暴风城港口搭船到奥伯丁，沿黑海岸往南进灰谷，从东边莫尔杉壁垒进贫瘠之地往南找塔卡尔；十字路口和陶拉祖营地是部落据点，要绕开。"}, [17]={npc="先知塔卡尔", tgt="先知塔卡尔"}, [18]={npc="先知塔卡尔", tgt="先知塔卡尔"}, [19]={hint="从灰谷取回同心树，把它交给暴风城法师区里的黑暗缚灵者加科因。", desc="先清掉树旁的怪，再点那棵塞纳里奥之树取得同心树。"}, [20]={hint="取得木雕，把它交给暴风城法师区里的黑暗缚灵者加科因。"}, [21]={npc="黑暗缚灵者加科因", tgt="黑暗缚灵者加科因", desc="灰谷做完用炉石回暴风城；炉石在冷却就往北回奥伯丁搭船到暴风城。"}, [22]={npc="黑暗缚灵者加科因", tgt="黑暗缚灵者加科因"}, [23]={npc="黑暗缚灵者加科因", tgt="黑暗缚灵者加科因", desc="在加科因旁的召唤法阵使用，击败召唤出的魅魔。"}, [24]={hint="召唤并制服一个魅魔，然后将同心树之核还给已宰的羔羊旅店的黑暗缚灵者加科因。", desc="在加科因旁的召唤法阵使用，击败召唤出的魅魔。"}, [25]={npc="黑暗缚灵者加科因", tgt="黑暗缚灵者加科因", desc="在加科因旁的召唤法阵使用，击败召唤出的魅魔。"}, [26]={npc="黑暗缚灵者加科因", tgt="黑暗缚灵者加科因"}, [27]={hint="使用木雕召唤并制服一个夜魔，然后将木雕还给已宰的羔羊旅店的黑暗缚灵者加科因。"}, [28]={npc="黑暗缚灵者加科因", tgt="黑暗缚灵者加科因"}, [29]={text="从暴风城沿艾尔文森林大路往东，先到阿祖拉之塔找塞欧克瑞图斯接法师的眼线；接完再往东到赤脊山入口找卫兵帕克，然后沿大路进湖畔镇。", tag="还没开这个飞行点，第一次要用跑的、去赤脊山前，可以先在拍卖行买（或请小号寄来）8 片鱼人