    ["05-d4"] = {name="监狱", entrance="暴风城 52.41, 70.01", pickup="先在湖畔镇接伸张正义，再去夜色镇接罪与罚。监狱暴动需要先交范克里夫掉落的信；没有信就先做其他任务。完成湿地的黑铁战争后再组队做卡姆·深怒。", pickupS={{"先在湖畔镇接伸张正义，再去夜色镇接罪与罚"}, {"监狱暴动需要先交范克里夫掉落的信"}, {"没有信就先做其他任务"}, {"完成湿地的黑铁战争后再组队做卡姆·深怒"}}, steps={[1]={npc="议员米尔斯迪普", tgt="议员米尔斯迪普"}, [2]={text="前置：伸张正义"}, [3]={npc="未寄出的信", npcObj=true, tag="掉落才接", desc="死亡矿井范克里夫掉落，右键接任务。"}, [4]={npc="巴隆斯·阿历克斯顿", tgt="巴隆斯·阿历克斯顿"}, [5]={npc="巴隆斯·阿历克斯顿", tgt="巴隆斯·阿历克斯顿"}, [6]={npc="典狱官塞尔沃特", tgt="典狱官塞尔沃特"}, [7]={npc="典狱官塞尔沃特", tgt="典狱官塞尔沃特"}, [8]={npc="典狱官塞尔沃特", tgt="典狱官塞尔沃特"}, [9]={npc="尼科瓦·拉斯克", tgt="尼科瓦·拉斯克"}, [10]={text="监狱 入口"}, [11]={hint="暴风城的典狱官塞尔沃特要求你杀死监狱中的10名迪菲亚囚徒、8名迪菲亚罪犯和8名迪菲亚叛军。"}, [12]={hint="杀死巴基尔·斯瑞德，把他的头带给监狱的典狱官塞尔沃特。"}, [13]={hint="暴风城的尼科瓦·拉斯克要你取得10条红色毛纺面罩。"}, [14]={hint="夜色镇的米尔斯迪普议员要你杀死迪克斯特·瓦德，并把他的手带回来作为证明。"}, [15]={hint="把塔格尔的头颅带给湖畔镇的卫兵伯尔顿。", tag="有队伍再做、可选"}, [16]={hint="丹莫德的莫特雷·加玛森要求你把卡姆·深怒的头颅交给他。", tag="有队伍再做、可选"}, [17]={npc="典狱官塞尔沃特", tgt="典狱官塞尔沃特"}, [18]={npc="典狱官塞尔沃特", tgt="典狱官塞尔沃特"}, [19]={npc="尼科瓦·拉斯克", tgt="尼科瓦·拉斯克"}, [20]={npc="卫兵伯尔顿", tgt="卫兵伯尔顿", tag="有队伍再做、可选、之后顺路", desc="留到 「{s:02-19}」，经过湖畔镇再交。"}, [21]={npc="议员米尔斯迪普", tgt="议员米尔斯迪普", tag="可选、有队伍再做、之后顺路", desc="留到 「{s:03-22}」，经过夜色镇再交。"}, [22]={npc="莫特雷·加玛森", tgt="莫特雷·加玛森", tag="有队伍再做、之后顺路"}}},
    ["02-18"] = {steps={[1]={npc="典狱官塞尔沃特", tgt="典狱官塞尔沃特", desc="打完暴风城监狱（监狱暴动）才接得到。"}, [2]={npc="巴隆斯·阿历克斯顿", tgt="巴隆斯·阿历克斯顿"}, [3]={npc="巴隆斯·阿历克斯顿", tgt="巴隆斯·阿历克斯顿"}, [4]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔"}, [5]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔"}, [6]={npc="埃林·提亚斯", tgt="埃林·提亚斯"}, [7]={npc="埃林·提亚斯", tgt="埃林·提亚斯"}, [8]={npc="泰里恩", tgt="泰里恩"}, [9]={npc="泰里恩", tgt="泰里恩", tag="可选、材料齐了才做", desc="丝绸 ×3 可以在拍卖行买。"}}},
    ["02-19"] = {steps={[1]={to="Lakeshire", toA="{a:69}"}, [2]={npc="工头奥斯洛", tgt="工头奥斯洛"}, [3]={npc="弗纳·奥斯古", tgt="弗纳·奥斯古"}, [4]={npc="多林·桑布雷德", tgt="多林·桑布雷德", tag="可选、有队伍再做"}, [5]={npc="多林·桑布雷德", tgt="多林·桑布雷德", tag="可选、有队伍再做", desc="如果之前已经打过湿地挖掘场，在湖畔镇接下这个任务，下次组队进本时再去找戴文。"}, [6]={npc="通缉：加塞尔佐格", npcObj=true, tag="可选、有队伍再做"}, [7]={npc="通缉：焚化者加因姆", npcObj=true, tag="可选、有队伍再做"}, [8]={npc="所罗门镇长", tgt="所罗门镇长"}, [9]={npc="所罗门镇长", tgt="所罗门镇长"}, [10]={npc="通缉：范高雷中尉", npcObj=true}, [11]={npc="玛蒂·詹罗斯", tgt="玛蒂·詹罗斯"}, [12]={hint="湖畔镇的玛蒂·詹罗斯要求你杀死贝利格拉布，并带回它的獠牙作为证明。"}, [13]={npc="治安官哈迦德", tgt="治安官哈迦德"}, [14]={npc="治安官哈迦德", tgt="治安官哈迦德"}, [15]={npc="治安官哈迦德", tgt="治安官哈迦德", desc="上楼拾取箱子。"}, [16]={npc="治安官哈迦德", tgt="治安官哈迦德"}, [17]={npc="塞欧克瑞图斯", tgt="塞欧克瑞图斯"}, [18]={npc="卫兵豪维", tgt="卫兵豪维"}, [19]={hint="把焚化者加因姆的断裂法杖交给湖畔镇的所罗门镇长。", tag="可选、有队伍再做"}, [20]={npc="石狮子", npcObj=true, desc="去伊尔加拉之塔东边，在塔外找石狮子放置饰品。"}, [21]={npc="石狮子", npcObj=true, tag="可选、有队伍再做", desc="若找不到任务发给你的饰品，先检查背包、银行和任务日志。"}, [22]={hint="从石狮子向西去石望要塞旁完好的哨塔。沿塔内坡道上到塔顶，找桶上的空罐子。留意精英守卫。", tag="可选、有队伍再做"}, [23]={npc="空瓶子", npcObj=true, tag="可选、有队伍再做", desc="空瓶子在哨塔顶；后续 莫甘斯 不排。"}, [24]={hint="杀死加塞尔佐格并把他的头颅割下，向湖畔镇的所罗门镇长复命。", tag="可选、有队伍再做"}, [25]={hint="将萨瑞尔祖恩的头颅带给湖畔镇的治安官马瑞斯。", tag="可选、有队伍再做"}, [26]={hint="给湖畔镇的治安官马瑞斯带回3颗午夜宝珠。", tag="可选、有队伍再做"}, [27]={hint="给湖畔镇大厅的拜里弗·科纳彻尔带回10个暗皮坠饰。", desc="沿山谷东侧向北部营地走，沿路击杀暗皮豺狼人收集坠饰。山谷外围也有等级较低的豺狼人。"}, [28]={hint="在赤脊山伊尔加拉之塔内沿楼梯上楼，从书架上拿书。留意守卫和精英怪。 太危险时可以以后再来。", desc="在赤脊山伊尔加拉之塔内沿楼梯上楼，从书架上拿书。留意守卫和精英怪。 太危险时可以以后再来。"}, [29]={hint="杀死范高雷并将他的手掌割下，向湖畔镇的所罗门镇长复命。", desc="从山谷南侧沿东边向北找范高雷中尉。从营地边缘先清理附近的暗皮豺狼人，再靠近他。如果还缺坠饰，可以沿路收集。"}, [30]={hint="为赤脊山的工头奥斯洛消灭奥瑟尔伐木场的12只巨型狼蛛，并摧毁6枚狼蛛卵。"}, [31]={hint="杀死15名黑石勇士，并向湖畔镇的卫兵豪维复命。", desc="沿通往燃烧平原的道路前往西侧营地。先在洞口附近找黑石勇士，击杀数不够再往洞内找。以任务日志为准。"}, [32]={hint="将犹勒的爪子带回给湖畔镇的弗纳·奥斯古。"}, [33]={npc="玛蒂·詹罗斯", tgt="玛蒂·詹罗斯"}, [34]={npc="拜里弗·科纳彻尔", tgt="拜里弗·科纳彻尔"}, [35]={npc="所罗门镇长", tgt="所罗门镇长", tag="可选、有队伍再做"}, [36]={npc="所罗门镇长", tgt="所罗门镇长"}, [37]={npc="所罗门镇长", tgt="所罗门镇长", tag="可选、有队伍再做"}, [38]={npc="弗纳·奥斯古", tgt="弗纳·奥斯古"}, [39]={npc="工头奥斯洛", tgt="工头奥斯洛"}, [40]={npc="治安官马瑞斯", tgt="治安官马瑞斯", tag="可选"}, [41]={npc="治安官马瑞斯", tgt="治安官马瑞斯", tag="可选"}, [42]={npc="卫兵豪维", tgt="卫兵豪维"}, [43]={to="Darkshire", toA="{a:42}"}, [44]={npc="旅店老板斯密茨", tgt="旅店老板斯密茨"}, [45]={npc="旅店老板斯密茨", tgt="旅店老板斯密茨"}, [46]={npc="厨师格鲁奥", tgt="厨师格鲁奥"}, [47]={npc="厨师格鲁奥", tgt="厨师格鲁奥"}, [48]={npc="指挥官阿尔泰娅·埃伯洛克", tgt="指挥官阿尔泰娅·埃伯洛克"}, [49]={npc="指挥官阿尔泰娅·埃伯洛克", tgt="指挥官阿尔泰娅·埃伯洛克"}, [50]={npc="书记员达尔塔", tgt="书记员达尔塔"}, [51]={npc="书记员达尔塔", tgt="书记员达尔塔"}, [52]={npc="艾尔罗·埃伯洛克公爵", tgt="艾尔罗·埃伯洛克公爵"}, [53]={npc="指挥官阿尔泰娅·埃伯洛克", tgt="指挥官阿尔泰娅·埃伯洛克"}, [54]={npc="指挥官阿尔泰娅·埃伯洛克", tgt="指挥官阿尔泰娅·埃伯洛克"}, [55]={hint="收集8份任务蛛丝。夜色镇东南有小型黑寡妇蜘蛛；西侧乌鸦岭的地表有小型黑寡妇蜘蛛和食腐独行蛛。"}, [56]={}, [57]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="需要亚麻布 ×10和充能裂隙宝石 ×6。若顺路回洛克莫丹，可从银泉矿洞北口（约35.9,18.2）进洞开矿工的箱子。缺材料先走主线，任务日志显示可交时再到暴风城找裁缝。"}, [58]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="奖励法纹长袍。"}, [59]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="奖励法纹长袍。"}, [60]={npc="高阶巫师安多玛斯", tgt="高阶巫师安多玛斯"}, [61]={npc="高阶巫师安多玛斯", tgt="高阶巫师安多玛斯"}, [62]={npc="高阶巫师安多玛斯", tgt="高阶巫师安多玛斯", desc="接任务后，顺路经过暮色森林时收集蛛丝。去乌鸦岭做惩罚图腾也会经过这些蜘蛛。"}, [63]={npc="维恩·拉尔森", tgt="维恩·拉尔森"}, [64]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="奖励星结之衣。"}, [65]={npc="维恩·拉尔森", tgt="维恩·拉尔森", desc="奖励星结之衣。"}}},
    ["02-20"] = {steps={[1]={to="奥伯丁", from="Stormwind", desc="在暴风城港口的码头上船。"}, [2]={npc="特伦希斯", tgt="特伦希斯"}, [3]={to="Astranaar", toA="{a:415}"}, [4]={npc="法德瑞斯·戈森沙尔", tgt="法德瑞斯·戈森沙尔"}, [5]={npc="莱恩·狼行者", tgt="莱恩·狼行者"}, [6]={npc="莱恩·狼行者", tgt="莱恩·狼行者"}, [7]={npc="莱恩·狼行者", tgt="莱恩·狼行者"}, [8]={text="出阿斯特兰纳先往东走到岔路口，再沿路往北。"}, [9]={hint="把达尔·血爪的颅骨交给阿斯特兰纳的莱恩·狼行者。"}, [10]={hint="找到月神之泪，把它交给阿斯特兰纳的皮尔图拉斯·怀特姆恩。"}, [11]={text="从湖心岛往南游回岸上（46.80, 49.20 → 47.00, 51.70），再往东走。"}, [12]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [13]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [14]={hint="找到木制钥匙和一段达图尔的魔棒，然后回到月亮井的莎尔蒂恩那里。"}, [15]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [16]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [17]={hint="杀掉污林部族里的1个污林卫兵、2个污林巨熊、2个污林萨满祭司和2个污林战士，然后回到阿斯特兰纳向莱恩·狼行者复命。"}, [18]={hint="找到达图尔的魔棒的最后一段，然后回到月亮井旁的莎尔蒂恩那里。"}, [19]={npc="闪亮的弯月坠饰", npcObj=true}, [20]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [21]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [22]={npc="隐蔽的神龛", npcObj=true}, [23]={npc="隐蔽的神龛", npcObj=true}, [24]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [25]={npc="莎尔蒂恩", tgt="莎尔蒂恩"}, [26]={npc="皮尔图拉斯·怀特姆恩", tgt="皮尔图拉斯·怀特姆恩"}, [27]={npc="皮尔图拉斯·怀特姆恩", tgt="皮尔图拉斯·怀特姆恩"}, [28]={npc="莱恩·狼行者", tgt="莱恩·狼行者"}, [29]={npc="莱恩·狼行者", tgt="莱恩·狼行者"}, [30]={npc="莱恩·狼行者", tgt="莱恩·狼行者"}, [31]={npc="玛琳", tgt="玛琳"}, [32]={hint="把伊克鲁德·玛格苏尔之书交给迈斯特拉岗哨的净化者德尔格伦。"}, [33]={npc="净化者德尔格伦", tgt="净化者德尔格伦"}, [34]={npc="净化者德尔格伦", tgt="净化者德尔格伦"}, [35]={hint="收集5份星尘，把它们交给灰谷的皮尔图拉斯·怀特姆恩。"}, [36]={text="走到山洞口（42.30, 71.00），穿过山洞进石爪山脉。"}, [37]={npc="凯拉·影矛", tgt="凯拉·影矛"}, [38]={npc="凯拉·影矛", tgt="凯拉·影矛"}, [39]={npc="加克希姆·尘链", tgt="加克希姆·尘链"}, [40]={npc="暗夜精灵信使", tgt="暗夜精灵信使", tag="可选"}, [41]={hint="从巨翼双足飞龙那里收集6份石爪补给品，并将它们交给旅店老板法拉莉亚。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [42]={npc="旅店老板法拉莉亚", tgt="旅店老板法拉莉亚", tag="可选"}, [43]={npc="守护者奥巴格姆", tgt="守护者奥巴格姆"}, [44]={nodeA="{a:467}", node="Stonetalon Peak"}, [45]={to="Astranaar", toA="{a:415}"}, [46]={npc="辛德瑞尔·速火", tgt="辛德瑞尔·速火"}, [47]={npc="皮尔图拉斯·怀特姆恩", tgt="皮尔图拉斯·怀特姆恩"}, [48]={to="奥伯丁"}, [49]={to="Stormwind", from="奥伯丁"}}},
    ["05-d5"] = {name="黑暗深渊", entrance="灰谷 14.50, 14.20", pickup="走到黑海岸 第二次时先接研究堕落；达纳苏斯和铁炉堡的三件要 18-20 级，到等级经过时再接。", pickupS={{"走到黑海岸 第二次时先接研究堕落"}, {"达纳苏斯和铁炉堡的三件要 18-20 级，到等级经过时再接"}}, steps={[1]={npc="戈沙拉·夜语", tgt="戈沙拉·夜语"}, [2]={npc="银月守卫玛纳杜斯", tgt="银月守卫玛纳杜斯", desc="要 20 级；「{s:02-13}」进达纳苏斯时还不到就之后经过再接，或略过。"}, [3]={npc="哨兵山德拉斯", tgt="哨兵山德拉斯", desc="要 18 级，「{s:02-13}」进达纳苏斯时顺接。"}, [4]={npc="葛利·硬骨", tgt="葛利·硬骨", desc="要 18 级；之后经过暴风城时搭矿道地铁到铁炉堡接，不想专程就略过。"}, [5]={text="黑暗深渊 入口"}, [6]={hint="把洛迦里斯手稿带给铁炉堡的葛利·硬骨。"}, [7]={hint="奥伯丁的戈沙拉·夜语需要8块堕落者的脑干。"}, [8]={npc="银月守卫塞尔瑞德", tgt="银月守卫塞尔瑞德"}, [9]={npc="银月守卫塞尔瑞德", tgt="银月守卫塞尔瑞德"}, [10]={hint="收集10个暮光坠饰，把它们交给达纳苏斯的银月守卫玛纳杜斯。"}, [11]={hint="把暮光领主克尔里斯的头颅交给达纳苏斯的哨兵塞尔高姆。"}, [12]={npc="戈沙拉·夜语", tgt="戈沙拉·夜语"}, [13]={npc="银月守卫玛纳杜斯", tgt="银月守卫玛纳杜斯"}, [14]={npc="哨兵塞尔高姆", tgt="哨兵塞尔高姆"}, [15]={npc="葛利·硬骨", tgt="葛利·硬骨"}}},
