    ["03-23"] = {steps={[1]={npc="萨尔努修士", tgt="萨尔努修士"}, [2]={npc="沉默的舒尼", tgt="沉默的舒尼", tag="有队伍再做、可选", desc="诺莫瑞根副本任务，要打诺莫瑞根才接。"}, [3]={to="Menethil Harbor", toA="{a:150}"}, [4]={npc="塞莱莎·暮语", tgt="塞莱莎·暮语"}, [5]={npc="戈罗林·钢眉", tgt="戈罗林·钢眉"}, [6]={npc="戈罗林·钢眉", tgt="戈罗林·钢眉"}, [7]={npc="大副菲兹莫斯", tgt="大副菲兹莫斯"}, [8]={npc="哈尔罗·巴纳比", tgt="哈尔罗·巴纳比"}, [9]={npc="斯托菲队长", tgt="斯托菲队长"}, [10]={npc="斯托菲队长", tgt="斯托菲队长"}, [11]={npc="浸水的箱子", npcObj=true}, [12]={npc="浸水的箱子", npcObj=true}, [13]={hint="为米奈希尔港的塞莱莎·暮语找回诺德尔。"}, [14]={npc="塞莱莎·暮语", tgt="塞莱莎·暮语"}, [15]={hint="收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。"}, [16]={npc="戈罗林·钢眉", tgt="戈罗林·钢眉"}, [17]={npc="戈罗林·钢眉", tgt="戈罗林·钢眉"}, [18]={hint="消灭13名被诅咒的水手、5名被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔港的大副菲兹莫斯。"}, [19]={npc="大副菲兹莫斯", tgt="大副菲兹莫斯"}, [20]={npc="大副菲兹莫斯", tgt="大副菲兹莫斯"}, [21]={hint="从哈林多尔船长那里拿到无畏号的保险箱钥匙。", desc="哈林多尔船长在搁浅的无畏号上，先杀他拿钥匙，再开船上的保险箱。"}, [22]={npc="保险箱", npcObj=true}, [23]={npc="保险箱", npcObj=true}, [24]={npc="奥莫尔·铁衣", tgt="奥莫尔·铁衣"}, [25]={npc="勘察员维尔加", tgt="勘察员维尔加"}, [26]={hint="奥莫尔·铁衣要求你杀死10只杂斑镰爪龙和10只杂斑刺喉龙，然后返回维尔加挖掘场向他复命。"}, [27]={hint="勘察员维尔加要求你在挖掘场中搜索4块石板的碎片，它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片。"}, [28]={npc="奥莫尔·铁衣", tgt="奥莫尔·铁衣"}, [29]={npc="奥莫尔·铁衣", tgt="奥莫尔·铁衣"}, [30]={npc="勘察员维尔加", tgt="勘察员维尔加"}, [31]={npc="泰坦圣物", npcObj=true, tag="可选、掉落才接", desc="打倒遗迹守卫者后，如果拾到泰坦圣物，右键接任务。"}, [32]={npc="勘察员维尔加", tgt="勘察员维尔加"}, [33]={npc="勘察员维尔加", tgt="勘察员维尔加"}, [34]={text="萨尔图斯在山坡上，要照箭头从西边绕上去（31.99, 48.68 → 31.15, 49.05 → 32.41, 50.92）。"}, [35]={hint="维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。"}, [36]={npc="奥莫尔·铁衣", tgt="奥莫尔·铁衣"}, [37]={npc="霍文·鹰羽", tgt="霍文·鹰羽"}, [38]={npc="霍文·鹰羽", tgt="霍文·鹰羽"}, [39]={npc="埃纳尔·石钳", tgt="埃纳尔·石钳", desc="送货任务，回米奈希尔港时交给詹姆斯·哈洛兰。"}, [40]={hint="米奈希尔城堡的斯托菲队长要你摧毁怒牙营地里的4份进攻计划。"}, [41]={npc="破损的法术书", npcObj=true, desc="怒牙营地里的书，捡起来带回米奈希尔港。"}, [42]={hint="黑爪加尔德斯要求你从夜色镇给他摘1朵蒂罗亚之泪，再从湿地给他采一块麝鼠根。"}, [43]={hint="收集8片无瑕的赤红鳞片，把它们交给米奈希尔港的詹姆斯·哈洛兰。"}, [44]={hint="给斯托菲队长带回8面龙喉战旗。"}, [45]={hint="为霍文·鹰羽收集12枚完美的刺喉龙蛋。"}, [46]={hint="替霍文·鹰羽收集10颗刺喉龙门牙。"}, [