    ["05-d7"] = {name="诺莫瑞根", entrance="丹莫罗 24.30, 39.80", pickup="走到灰谷 第二次时先接进本前的任务，进本前不必专程回头。", pickupS={{"走到灰谷 第二次时先接进本前的任务，进本前不必专程回头"}}, steps={[1]={npc="加克希姆·尘链", tgt="加克希姆·尘链"}, [2]={npc="萨尔努修士", tgt="萨尔努修士"}, [3]={npc="沉默的舒尼", tgt="沉默的舒尼", tag="有队伍再做、可选"}, [4]={npc="工匠大师欧沃斯巴克", tgt="工匠大师欧沃斯巴克", tag="有队伍再做、可选"}, [5]={npc="大工匠梅卡托克", tgt="大工匠梅卡托克", tag="有队伍再做、可选"}, [6]={npc="大机械师卡斯派普", tgt="大机械师卡斯派普", tag="有队伍再做、可选"}, [7]={npc="科罗莫特·钢尺", tgt="科罗莫特·钢尺"}, [8]={npc="诺恩", tgt="诺恩", tag="可选、有队伍再做"}, [9]={npc="奥齐·电环", tgt="奥齐·电环"}, [10]={npc="奥齐·电环", tgt="奥齐·电环", tag="可选、有队伍再做"}, [11]={npc="奥齐·电环", tgt="奥齐·电环", tag="可选、有队伍再做"}, [12]={npc="玛希尔", tgt="玛希尔", tag="可选", desc="达纳苏斯接，要 24 级：从奥伯丁飞鲁瑟兰村走传送门进城；不绕路就连同出本后的回交一起略过。"}, [13]={text="从米奈希尔港飞铁炉堡，出城门沿丹莫罗大路往西到诺莫瑞根。"}, [14]={text="诺莫瑞根 入口"}, [15]={hint="用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。", tag="可选、有队伍再做", spot="任务可分几趟完成。在入口通道或副本内采集第一份样本，回卡拉诺斯交给奥齐，领取沉重的铅瓶。"}, [16]={hint="到诺莫瑞根去收集高强度辐射尘。要多加小心，这种辐射尘非常不稳定，很快就会分解。", tag="可选、有队伍再做", spot="带沉重的铅瓶找辐射泥浆怪、酸性潜伏者或辐射水元素。样本只能保存两小时。如果不能及时回到卡拉诺斯，下次组队再采样。"}, [17]={hint="收集24副机械内胆，把它们交给暴风城的舒尼。", tag="有队伍再做、可选", desc="机械怪身上掉，回暴风城时交。"}, [18]={npc="脏兮兮的戒指", npcObj=true, tag="掉落才接、可选"}, [19]={hint="想方法把脏兮兮的戒指弄干净。", tag="可选", spot="清洁区的超级清洁器 5200 型。需要 3 银。"}, [20]={npc="超级清洁器5200型", npcObj=true, tag="可选"}, [21]={npc="超级清洁器5200型", npcObj=true, tag="可选"}, [22]={npc="克努比", tgt="克努比", tag="可选、有队伍再做", spot="清洁区旁的宿舍。先清理通往出口的路，等全队准备好再与克努比对话。"}, [23]={hint="将克努比护送到出口，然后向藏宝海湾的斯库提汇报。", tag="护送、可选、有队伍再做", desc="第一次路过荆棘谷的藏宝海湾时，找斯库提交任务。"}, [24]={npc="奥齐·电环", tgt="奥齐·电环", tag="可选、有队伍再做"}, [25]={npc="奥齐·电环", tgt="奥齐·电环", tag="可选、有队伍再做"}, [26]={npc="奥齐·电环", tgt="奥齐·电环", tag="可选、有队伍再做"}, [27]={npc="工匠大师欧沃斯巴克", tgt="工匠大师欧沃斯巴克"}, [28]={npc="工匠大师欧沃斯巴克", tgt="工匠大师欧沃斯巴克", tag="可选、有队伍再做"}, [29]={npc="大机械师卡斯派普", tgt="大机械师卡斯派普"}, [30]={npc="大机械师卡斯派普", tgt="大机械师卡斯派普", tag="可选、有队伍再做"}, [31]={npc="大工匠梅卡托克", tgt="大工匠梅卡托克", tag="可选、有队伍再做"}, [32]={npc="科罗莫特·钢尺", tgt="科罗莫特·钢尺", tag="可选、有队伍再做"}, [33]={npc="科罗莫特