    ["03-27"] = {steps={[1]={npc="詹妮亚·坎农", tgt="詹妮亚·坎农", tag="可以先在拍卖行买（或请小号寄来）1 颗翡翠（之后尘泥沼泽的强大的物品用）。", desc="到尘泥沼泽交给塔贝萨。"}, [3]={npc="埃林·提亚斯", tgt="埃林·提亚斯"}, [4]={npc="埃林·提亚斯", tgt="埃林·提亚斯"}, [5]={npc="达舍尔·石拳", tgt="达舍尔·石拳"}, [6]={npc="达舍尔·石拳", tgt="达舍尔·石拳"}, [7]={hint="击败暴风城的达舍尔·石拳。"}, [8]={npc="达舍尔·石拳", tgt="达舍尔·石拳"}, [9]={npc="达舍尔·石拳", tgt="达舍尔·石拳"}, [10]={npc="埃林·提亚斯", tgt="埃林·提亚斯"}, [11]={npc="埃林·提亚斯", tgt="埃林·提亚斯"}, [12]={text="到暴风城矮人区搭矿道地铁到铁炉堡。"}, [13]={npc="大石匠玛布勒斯坦", tgt="大石匠玛布勒斯坦"}, [14]={npc="大石匠玛布勒斯坦", tgt="大石匠玛布勒斯坦"}, [15]={npc="国王麦格尼·铜须", tgt="国王麦格尼·铜须"}, [16]={npc="葛利·硬骨", tgt="葛利·硬骨", tag="可选", desc="黑海岸捡到《深渊之神》的才交。"}, [17]={npc="资深探险家麦格拉斯", tgt="资深探险家麦格拉斯"}, [18]={npc="勘察员塔伯斯·雷矛", tgt="勘察员塔伯斯·雷矛"}, [19]={npc="勘察员塔伯斯·雷矛", tgt="勘察员塔伯斯·雷矛"}, [20]={npc="勘察员塔伯斯·雷矛", tgt="勘察员塔伯斯·雷矛"}, [21]={npc="勘察员塔伯斯·雷矛", tgt="勘察员塔伯斯·雷矛"}, [22]={npc="拉戈·黑钳", tgt="拉戈·黑钳"}, [23]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="铁炉堡飞藏宝海湾（经暴风城转机），搭船到棘齿城。"}, [24]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉"}, [25]={npc="克罗姆·粗臂", tgt="克罗姆·粗臂", desc="棘齿城搭船到藏宝海湾，飞铁炉堡。"}, [26]={npc="克罗姆·粗臂", tgt="克罗姆·粗臂"}, [27]={hint="为铁炉堡的克罗姆·粗臂找回发霉的书籍和破损的手稿。", desc="铁炉堡飞南海镇，回程飞铁炉堡。"}, [28]={npc="克罗姆·粗臂", tgt="克罗姆·粗臂"}, [29]={npc="克罗姆·粗臂", tgt="克罗姆·粗臂"}, [30]={hint="将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。", desc="铁炉堡飞米奈希尔港做湿地这段。"}, [31]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="米奈希尔港南码头搭船到塞拉摩，开飞行点后飞棘齿城；或从米奈希尔港飞藏宝海湾（经铁炉堡、暴风城）再搭船。"}, [32]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="在斯坦哈德附近的法阵召唤并击败地狱猎犬。"}, [33]={hint="召唤地狱猎犬并打败它，然后把阴谋之书交给棘齿城的斯坦哈德·法尔杉。", desc="在斯坦哈德附近的法阵召唤并击败地狱猎犬。"}, [34]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="在斯坦哈德附近的法阵召唤并击败地狱猎犬。"}, [35]={text="从棘齿城沿贫瘠之地大路往北，过十字路口后继续往北进灰谷，再沿灰谷大路往西到阿斯特兰纳（34.41, 47.99）。", desc="十字路口和碎木岗哨是部落据点，要绕开。飞行地图有塞拉摩的，可以直接飞阿斯特兰纳（经塞拉摩、奥伯丁转机）。"}, [36]={npc="科罗莫特·钢尺", tgt="科罗莫特·钢尺"}, [37]={npc="埃尔德伦·风暴破坏者", tgt="埃尔德伦·风暴破坏者", desc="空气的召唤，到阿拉希高地找维里克·雷锤。"}, [38]={to="Menethil Harbor", toA="{a:150}"}, [39]={npc="米克哈尔", tgt="米克哈尔"}, [40]={npc="米克哈尔", tgt="米克哈尔"}, [41]={hint="在塔伯克·贾恩逃跑前制服他，然后回米奈希尔港旅店去找米克哈尔。"}, [42]={npc="米克哈尔", tgt="米克哈尔"}, [43]={npc="Tapoke Slim Jahn", tgt="Tapoke Slim Jahn"}, [44]={npc="米克哈尔", tgt="米克哈尔"}, [45]={npc="米克哈尔", tgt="米克哈尔"}, [46]={npc="文森特·海厄尔", tgt="文森特·海厄尔", desc="同一间旅店里；送信到塞拉摩。"}, [47]={to="奥伯丁", from="Menethil Harbor", fromA="{a:150}", desc="这班船中途停南海镇，到奥伯丁再下船。"}}},
    ["03-28"] = {steps={[1]={to="Astranaar", toA="{a:415}"}, [2]={npc="哨兵梅丽瑞亚·霜影", tgt="哨兵梅丽瑞亚·霜影"}, [3]={npc="伊莉亚娜", tgt="伊莉亚娜"}, [4]={npc="皮尔图拉斯·怀特姆恩", tgt="皮尔图拉斯·怀特姆恩"}, [5]={text="先绕到北边，从这里进狼嚎谷。"}, [6]={hint="到狼嚎谷去，研究一下麦尔莎迪丝之书，然后向艾森娜神殿的哨兵梅丽瑞亚·霜影复命。", desc="从山洞进去拿书，容易多拉怪，稀有怪在时更难。"}, [7]={hint="从沼泽兽智者那里取回一枚陨落的月亮石，并把它带给阿斯特兰纳的皮尔图拉斯·怀特姆恩。"}, [8]={text="回到北边的大路，从这里的路口进夜道谷。"}, [9]={hint="在夜道谷和萨提纳尔找到被禁锢的上层精灵的灵魂，释放它们，然后回到迈斯特拉岗哨的净化者德尔格伦那里。"}, [10]={npc="安妮莉亚", tgt="安妮莉亚"}, [11]={npc="安妮莉亚", tgt="安妮莉亚"}, [12]={hint="杀掉加萨里斯，把塞纳留斯的树枝交给艾森娜神殿的伊莉亚娜。"}, [13]={npc="凯尼斯·静风", tgt="凯尼斯·静风"}, [14]={npc="马塞拉·秋月", tgt="马塞拉·秋月"}, [15]={hint="马塞拉·秋月要你前往林歌神殿以西、萨提纳尔恶魔盘踞的区域搜寻。回来后向她报告丈夫库罗塞尔的任何线索。"}, [16]={npc="马塞拉·秋月", tgt="马塞拉·秋月"}, [17]={nodeA="{a:3137}", node="Talrendis Point", desc="从林歌神殿沿大路往东进艾萨拉，营地就在入口旁。"}, [18]={to="Astranaar", toA="{a:415}"}, [19]={npc="皮尔图拉斯·怀特姆恩", tgt="皮尔图拉斯·怀特姆恩"}, [20]={npc="哨兵梅丽瑞亚·霜影", tgt="哨兵梅丽瑞亚·霜影"}, [21]={npc="哨兵梅丽瑞亚·霜影", tgt="哨兵梅丽瑞亚·霜影", tag="可选"}, [22]={npc="伊莉亚娜", tgt="伊莉亚娜"}, [23]={npc="净化者德尔格伦", tgt="净化者德尔格伦"}}},
    ["03-29"] = {grind={[1]={mob="盐石凝视者", note="闪光平原南端，普通怪，和安全隐患的蜥蜴同一区。"}, [2]={mob="盐石水晶蜥蜴", note="和凝视者混在一起，数量较多，等级略低。"}}, steps={[1]={to="Rut'theran Village", toA="{a:702}", tag="可选", desc="达纳苏斯这段经验少，赶路可跳过。"}, [2]={text="走进鲁瑟兰村的传送门到达纳苏斯。", tag="可选"}, [3]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [4]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [5]={hint="在维琳德的箱子里搜寻她的日记，把日记连同钥匙一起交给达纳苏斯的塞恩提尔·刃纹。", tag="可选"}, [6]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [7]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [8]={text="走进达纳苏斯的传送门回鲁瑟兰村。", tag="可选"}, [9]={text="做了达纳苏斯选做的从鲁瑟兰村飞棘齿城（经奥伯丁、塔伦迪斯营地），跳过的从阿斯特兰纳飞（经塔伦迪斯营地）；沿主路往南，绕开陶拉祖营地，搭大升降梯下千针石林。两点没开才走莫尔杉壁垒。"}, [10]={text="搭大升降梯下到底。"}, [11]={nodeA="{a:489}", node="Thalanaar"}, [12]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [13]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [14]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [15]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [16]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [17]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [18]={npc="普兹克", tgt="普兹克"}, [19]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [20]={hint="给闪光平原的普兹克找10根空心秃鹫骨。"}, [21]={hint="为闪光平原的赛道管理员泽尔林杀死10条盐石蜥蜴、10条盐石水晶蜥蜴和6条盐石凝视者。"}, [22]={hint="收集9块硬化龟壳，把它们交给闪光平原的维兹尔·铜栓。"}, [23]={hint="收集30个火箭车零件，把它们交给闪光平原的克拉维尔·浓须。"}, [24]={hint="为闪光平原的菲兹尔·铜栓带去6份含盐的蝎毒。"}, [25]={npc="普兹克", tgt="普兹克"}, [26]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [27]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [28]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [29]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [30]={desc="离开闪光平原前还不到 35 级，就在赛道南边打盐石凝视者、盐石水晶蜥蜴补到 35 级。"}, [31]={text="从闪光平原沿大路往南进塔纳利斯，到加基森开飞行点再炉石。", tag="还没开这个飞行点，第一次要用跑的"}, [32]={nodeA="{a:976}", node="Gadgetzan"}, [33]={}}},
    ["03-30"] = {name="阿拉希高地", grind={[1]={mob="枯须狗头人", note="枯须峡谷入口一带，普通怪，被困的公主做完就在旁边。"}, [2]={mob="枯须掘地工", note="峡谷深处水晶旁，等级较合适。"}, [3]={mob="石拳蛮兵", note="石拳大厅外围的食人魔，拿魔杖时顺路。"}, [4]={mob="枯木暗影猎手", note="东南的枯木村，和证明实力同一批巨魔。"}}, steps={[1]={to="Refuge Pointe", toA="{a:320}", desc="避难谷地没开就飞米奈希尔港，沿湿地大路往东北，过萨多尔大桥进阿拉希高地，再沿大路到避难谷地。"}, [2]={npc="尼艾丝队长", tgt="尼艾丝队长"}, [3]={npc="通缉板", npcObj=true, tag="有队伍再做、可选"}, [4]={npc="通缉板", npcObj=true, tag="有队伍再做、可选", desc="奥图和法库雷斯特是 38、40 级精英。"}, [5]={npc="斯奎尔图", tgt="斯奎尔图"}, [6]={npc="学徒克里汀", tgt="学徒克里汀"}, [7]={npc="密斯莱尔水晶碎块", npcObj=true}, [8]={hint="收集密斯莱尔之尘。"}, [9]={npc="虹光水晶碎块", npcObj=true}, [10]={desc="练到 36 级约四分之三；就在枯须峡谷打枯须狗头人和掘地工。"}, [11]={npc="虹光水晶碎块", npcObj=true, desc="东禁锢之石就在往西的路上，先拿；外禁锢之石在去避难谷地途中拿。"}, [12]={npc="奎艾", tgt="奎艾"}, [13]={npc="奎艾", tgt="奎艾"}, [14]={hint="找到被遗忘者信使，把她的密封的信件交给格沙克农场里的奎艾。", desc="被遗忘者信使沿格沙克农场一带的大路巡逻，看到就打，拿密封的信件。"}, [15]={hint="帮避难谷地中的学徒克里汀收集10个枯木巨魔的獠牙，4只枯木巨魔的医药包和1把暗影猎手的小刀。", desc="留意巡逻的被遗忘者信使。"}, [16]={npc="学徒克里汀", tgt="学徒克里汀"}, [17]={npc="尼艾丝队长", tgt="尼艾丝队长", desc="交件在大河林地法霍德要塞的德玛尔·布兰特，下一站会去。"}, [18]={npc="斯奎尔图", tgt="斯奎尔图"}, [19]={desc="打考格雷什（39 级）前还不到 37 级，就在石拳大厅外打石拳蛮兵，或到东边枯木村打枯木巨魔补到 37。"}, [20]={hint="帮避难谷地的斯奎尔图找到特雷莱恩的符咒魔杖，并把它带回来。"}, [21]={npc="奎艾", tgt="奎艾"}, [22]={npc="奎艾", tgt="奎艾"}, [23]={npc="基恩洛", tgt="基恩洛"}, [24]={npc="基恩洛", tgt="基恩洛"}, [25]={hint="保护基恩洛，直到她回到奎艾身边。", desc="护送任务，跟着基恩洛走，途中会有伏击。"}, [26]={npc="奎艾", tgt="奎艾"}, [27]={npc="奎艾", tgt="奎艾"}, [28]={npc="斯奎尔图", tgt="斯奎尔图"}, [29]={npc="斯奎尔图", tgt="斯奎尔图", tag="有队伍再做、可选"}, [30]={hint="从西禁锢之石、东禁锢之石和外禁锢之石中搜集烈焰钥匙、海浪钥匙和雷霆钥匙。"}, [31]={hint="杀掉6个辛迪加雇佣兵和10个辛迪加路霸，然后回到避难谷地去向尼艾丝队长复命。"}, [32]={npc="尼艾丝队长", tgt="尼艾丝队长"}, [33]={npc="尼艾丝队长", tgt="尼艾丝队长", tag="有队伍再做、可选"}, [34]={npc="内禁锢之石", npcObj=true}, [35]={hint="把玛雷兹的头颅交给避难谷地的尼艾丝队长。", tag="有队伍再做、可选"}, [36]={hint="把法库雷斯特和奥图的头颅交给避难谷地的尼艾丝队长。", tag="有队伍再做、可选"}, [37]={hint="把激流堡徽章交给位于避难谷地的尼艾丝队长。", tag="有队伍再做、可选"}, [38]={hint="找到一块碧蓝玛瑙石，把它交给避难谷地处的学徒克里汀。", tag="有队伍再做、可选"}, [39]={npc="尼艾丝队长", tgt="尼艾丝队长", tag="有队伍再做、可选"}, [40]={npc="尼艾丝队长", tgt="尼艾丝队长", tag="有队伍再做、可选"}, [41]={npc="尼艾丝队长", tgt="尼艾丝队长", tag="有队伍再做、可选"}, [42]={npc="学徒克里汀", tgt="学徒克里汀", tag="有队伍再做、可选"}, [43]={npc="学徒克里汀", tgt="学徒克里汀"}, [44]={npc="斯奎尔图", tgt="斯奎尔图"}, [45]={npc="斯奎尔图", tgt="斯奎尔图"}, [46]={hint="找到特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙，把它们交给避难谷地的斯奎尔图。", tag="之后顺路"}, [47]={npc="斯奎尔图", tgt="斯奎尔图"}, [48]={npc="斯奎尔图", tgt="斯奎尔图"}, [49]={hint="从诺斯弗德农场弄一套辛迪加制服，用来潜入激流堡。", desc="从阿拉希高地的诺斯弗德农场偷辛迪加制服。"}, [50]={npc="辛迪加储物箱", npcObj=true}, [51]={npc="辛迪加储物箱", npcObj=true}, [52]={hint="伪装成辛迪加成员，在激流堡内打探出了解秘密交易的人。"}, [53]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒"}, [54]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒"}, [55]={hint="在激流堡内找些东西，用来让安娜斯塔西娅松口透露秘密交易的详情。"}, [56]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒"}, [57]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒"}, [58]={hint="破坏秘密交易，夺走要交给辛迪加的物品，然后回拉文霍德庄园向麦洛克斯复命。"}, [59]={npc="麦洛克斯", tgt="麦洛克斯"}, [60]={npc="维里克·雷锤", tgt="维里克·雷锤"}, [61]={npc="维里克·雷锤", tgt="维里克·雷锤", tag="有队伍再做、可选", desc="要打剃刀沼泽（贫瘠之地南边的副本），组到队伍再做；后续的风暴、大地与火焰也一起略过。"}, [62]={hint="在剃刀沼泽击败卡尔加·刺肋，收集有关野猪人计划的情报。", tag="有队伍再做、可选"}, [63]={npc="维里克·雷锤", tgt="维里克·雷锤", tag="有队伍再做、可选", desc="维里克·雷锤在铁炉堡（47.10, 13.79）也找得到。"}, [64]={npc="维里克·雷锤", tgt="维里克·雷锤", tag="可选", desc="四种扭曲的图腾在尘泥沼泽、荒芜之地、悲伤沼泽、凄凉之地的怪身上掉，后面几站沿路收；最后到铁炉堡找维里克·雷锤交。"}, [65]={to="Southshore", toA="{a:271}"}, [66]={npc="费恩·奥德利克", tgt="费恩·奥德利克"}, [67]={npc="赫尼·马雷布镇长", tgt="赫尼·马雷布镇长"}, [68]={desc="炉石还在冷却就从南海镇飞铁炉堡，搭矿道地铁回暴风城。"}}},
    ["05-d8"] = {name="血色修道院", entrance="提瑞斯法林地 82.60, 33.80", pickup="走到湿地 第二次时先接进本前的任务，进本前不必专程回头。", pickupS={{"走到湿地 第二次时先接进本前的任务，进本前不必专程回头"}}, steps={[1]={npc="图书馆员麦伊·苍尘", tgt="图书馆员麦伊·苍尘"}, [2]={to="Southshore", toA="{a:271}", desc="会经铁炉堡转机。"}, [3]={npc="虔诚的莱雷恩", tgt="虔诚的莱雷恩", tag="可选"}, [4]={npc="虔诚的莱雷恩", tgt="虔诚的莱雷恩", tag="可选、有队伍再做"}, [5]={npc="大法师奥尔韦克", tgt="大法师奥尔韦克", tag="可选"}, [6]={text="从希尔斯布莱德往西进银松森林，再沿大路北上进提里斯法林地。沿外围道路避开瑟伯切尔、幽暗城和布瑞尔的守卫，走到东北角的血色修道院。"}, [7]={text="血色修道院 入口"}, [8]={hint="从修道院拿回《泰坦神话》，把它交给铁炉堡的图书馆员麦伊·苍尘。", desc="位置：图书馆后段的书架。", spot="图书馆后段的书架。"}, [9]={hint="从血色修道院取回《符文大师的失落魔法》。", tag="可选"}, [10]={hint="杀死大检察官怀特迈恩，血色十字军指挥官莫格莱尼，十字军的勇士赫洛德和驯犬者洛克希并向南海镇的莱雷恩复命。", tag="可选", desc="在图书馆击败洛克希，在武器库击败赫洛德，在大教堂击败莫格莱尼和怀特迈恩。可以分几次完成。"}, [11]={npc="大法师奥尔韦克", tgt="大法师奥尔韦克", tag="可选"}, [12]={npc="虔诚的莱雷恩", tgt="虔诚的莱雷恩", tag="可选、材料齐了才做"}, [13]={npc="图书馆员麦伊·苍尘", tgt="图书馆员麦伊·苍尘", tag="可选", desc="离开血色后沿提瑞斯法和银松森林原路回南海镇。有航线就飞铁炉堡，否则搭船到米奈希尔港，沿湿地南部的山路进入洛克莫丹，穿过隧道到丹莫罗，再前往铁炉堡。如果炉石绑定暴风城且可以使用，也可炉回去搭矿道地铁。"}}},
    ["03-31"] = {tips={{k="提醒", text="地图中央的洛格玛是部落城镇，别靠近。", s={{"地图中央的洛格玛是部落城镇，别靠近"}}}}, steps={[1]={to="Lakeshire", toA="{a:69}", tag="去大河林地前，可以先在拍卖行买（或请小号寄来）8 个坚固的磨刀石（最锋利的刀刃用）。", desc="法霍德要塞还没开飞行点，第一次要从湖畔镇沿大路往东走进大河林地西口。"}, [2]={npc="多林·桑布雷德", tgt="多林·桑布雷德", tag="可选、有队伍再做"}, [3]={text="过了赤脊山东边的入口就是刺毛丘陵，入口一带的豺狼人 36-38 级，打起来痛。", tag="还没开这个飞行点，第一次要用跑的"}, [4]={npc="斥候博莱恩", tgt="斥候博莱恩"}, [5]={npc="塞德里克·道尔顿", tgt="塞德里克·道尔顿"}, [6]={npc="塞德里克·道尔顿", tgt="塞德里克·道尔顿"}, [7]={npc="塞德里克·道尔顿", tgt="塞德里克·道尔顿"}, [8]={npc="塞德里克·道尔顿", tgt="塞德里克·道尔顿", tag="可选、有队伍再做", desc="斯纳格尔是 40 级精英，打不过就跳过。"}, [9]={npc="柯里", tgt="柯里"}, [10]={npc="哈利根·特纳", tgt="哈利根·特纳"}, [11]={npc="哈利根·特纳", tgt="哈利根·特纳"}, [12]={npc="赫利", tgt="赫利"}, [13]={npc="赫利", tgt="赫利"}, [14]={hint="和赫利一起去救柯里。", desc="跟着赫利去救柯里。"}, [15]={hint="为南哨的塞德里克·道尔顿消灭8个赤脊山秘法师、8个赤脊山捕兽者和6个赤脊山蛮兵。"}, [16]={hint="为伐木厂的哈利根·特纳从刺毛丘陵的豺狼人营地找回8个锯齿利刃。", desc="锯齿利刃散在豺狼人营地地上。"}, [17]={hint="在刺毛丘陵找到并杀死斯纳格尔，把他的徽记带给南哨的塞德里克·道尔顿。", tag="可选、有队伍再做", desc="斯纳格尔是 40 级精英，打不过就跳过。"}, [18]={npc="哈利根·特纳", tgt="哈利根·特纳"}, [19]={npc="哈利根·特纳", tgt="哈利根·特纳"}, [20]={npc="埃莉诺·霍尔姆斯比", tgt="埃莉诺·霍尔姆斯比"}, [21]={npc="罗比·霍尔姆斯比", tgt="罗比·霍尔姆斯比"}, [22]={npc="守夜人弗雷德里克斯", tgt="守夜人弗雷德里克斯"}, [23]={npc="塞德里克·道尔顿", tgt="塞德里克·道尔顿"}, [24]={npc="塞德里克·道尔顿", tgt="塞德里克·道尔顿", tag="可选"}, [25]={npc="本吉·惠勒", tgt="本吉·惠勒"}, [26]={hint="在惠勒的垦野附近的河畔消灭8个泥鳍智者和8个泥鳍战士。"}, [27]={hint="收集4个巨型小龙虾壳、4份新鲜的粪便，以及8个泥鳍鱼人头，交给哈利根·特纳。", desc="泥鳍鱼人头颅和淡水恶魔一起打，再往北打巨型小龙虾、捡新鲜肥料。"}, [28]={hint="在河边鱼人出没的某个地方寻找罗比的帽子。", desc="在泥鳍鱼人营地找帽子。"}, [29]={nodeA="{a:16724}", node="Farholde Keep"}, [30]={npc="德玛尔·布兰特", tgt="德玛尔·布兰特"}, [31]={npc="德玛尔·布兰特", tgt="德玛尔·布兰特"}, [32]={npc="德玛尔·布兰特", tgt="德玛尔·布兰特"}, [33]={npc="德玛尔·布兰特", tgt="德玛尔·布兰特"}, [34]={npc="艾什·安伯霍尔", tgt="艾什·安伯霍尔"}, [35]={npc="艾什·安伯霍尔", tgt="艾什·安伯霍尔"}, [36]={npc="余烬·刃语", tgt="余烬·刃语"}, [37]={npc="罗兰修女", tgt="罗兰修女"}, [38]={npc="伯特兰·铁眉", tgt="伯特兰·铁眉"}, [39]={npc="卡桑德拉·惠勒", tgt="卡桑德拉·惠勒"}, [40]={hint="为罗兰修女在法霍德教堂消灭5只栖息的夜行蝙蝠。"}, [41]={npc="罗兰修女", tgt="罗兰修女"}, [42]={npc="罗兰修女", tgt