    ["03-36"] = {steps={[1]={to="Darkshire", toA="{a:42}"}, [2]={npc="守卫队长索里加尔", tgt="守卫队长索里加尔"}, [3]={text="从夜色镇往东过逆风小径进悲伤沼泽。"}, [4]={npc="卫兵比格斯", tgt="卫兵比格斯"}, [5]={hint="为藏宝海湾的克拉兹克收集10份梦境之尘。"}, [6]={hint="杀死8只小盐齿鳄鱼、10只沼泽纺丝蛛和10只沼泽虎，然后返回悲伤沼泽向卫兵比格斯复命。"}, [7]={npc="卫兵比格斯", tgt="卫兵比格斯"}, [8]={npc="卫兵比格斯", tgt="卫兵比格斯"}, [9]={npc="诺博鲁的木棒", npcObj=true, tag="可选", desc="右键背包里的诺博鲁的木棒接任务。；打木棒诺博鲁拿到灰色的棍棒，右键开任务。"}, [10]={npc="玛格图尔", tgt="玛格图尔", tag="可选"}, [11]={npc="玛格图尔", tgt="玛格图尔"}, [12]={hint="给悲伤沼泽避难营地里的玛格图尔带去6块德莱尼水晶。"}, [13]={hint="在农田避难所中找到商队的货物，并拿到巫师的材料，把它交给卫兵比格斯。"}, [14]={npc="加林·古瓦德", tgt="加林·古瓦德"}, [15]={hint="护送加林逃出困境，然后打开他放在悲伤沼泽营地里的保险箱。", tag="护送", desc="跟着加林走出农田避难所（失落者的营地），路上的怪会打他要保护；护送完再去他的营地开保险箱。"}, [16]={npc="加林的保险箱", npcObj=true}, [17]={npc="玛格图尔", tgt="玛格图尔"}, [18]={npc="卫兵比格斯", tgt="卫兵比格斯"}, [19]={npc="卫兵比格斯", tgt="卫兵比格斯"}, [20]={hint="给悲伤沼泽的卫兵比格斯带回8块晒干的流木。"}, [21]={hint="暴风城的布罗哈恩·铁桶要求你去找到阿塔哈卡神庙。", desc="走近沉没的神庙就完成。"}, [22]={npc="卫兵比格斯", tgt="卫兵比格斯"}, [23]={npc="卫兵比格斯", tgt="卫兵比格斯"}, [24]={text="从悲伤沼泽南边进诅咒之地，沿路往南到守望堡。", tag="还没开这个飞行点，第一次要用跑的"}, [25]={npc="军需官朗格尔斯", tgt="军需官朗格尔斯"}, [26]={nodeA="{a:1438}", node="Nethergarde Keep"}}},
