    ["03-38"] = {steps={[1]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德"}, [2]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德", desc="在勇士岛的竞技场连续击败四波对手。"}, [3]={hint="杀掉比格维尔，然后向勇士岛的克兰诺克·马克雷德回复。", desc="在勇士岛的竞技场连续击败四波对手。"}, [4]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德", desc="在勇士岛的竞技场连续击败四波对手。"}, [5]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德"}, [6]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="要一件奥法之袍，可请裁缝做或在拍卖行买。"}, [7]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="要一件奥法之袍，可请裁缝做或在拍卖行买。"}, [8]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="金锭 ×1 可以在拍卖行买。"}, [9]={hint="将一块金锭交给荆棘谷的希兹克·古斯提。"}, [10]={npc="希兹克·古斯提", tgt="希兹克·古斯提", desc="棘齿城搭船到藏宝海湾。"}, [11]={npc="希兹克·古斯提", tgt="希兹克·古斯提"}, [12]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="藏宝海湾搭船回棘齿城。"}, [13]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德"}, [14]={hint="将10瓶怨怒萨特之血和1块次级地狱火石交给贫瘠之地的梅纳拉·沃伦德。"}, [15]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德"}, [16]={npc="希兹克·古斯提", tgt="希兹克·古斯提", desc="棘齿城搭船到藏宝海湾。"}, [17]={npc="希兹克·古斯提", tgt="希兹克·古斯提"}, [18]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="藏宝海湾搭船回棘齿城。"}, [19]={hint="将一些优质金线、2块闷烧煤和一块灵魂碎片交给贫瘠之地的梅纳拉·沃伦德。", desc="阿拉希这段：棘齿城搭船到藏宝海湾，飞避难谷地（经暴风城、铁炉堡转机）；回程反向。"}, [20]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德"}, [21]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="奖励魔化金线血袍。"}, [22]={hint="等待梅纳拉·沃伦德织好披风，然后跟她谈一谈。", desc="奖励魔化金线血袍。"}, [23]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="奖励魔化金线血袍。"}, [24]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德"}, [25]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德"}, [26]={npc="助手温图拉", tgt="助手温图拉", desc="地狱犬碎片，和 地狱火的灵魂 二选一。"}, [27]={npc="助手玛迦兹", tgt="助手玛迦兹", tag="可选", desc="地狱火碎片，和 地狱犬的灵魂 二选一。"}, [28]={hint="在棘齿城外的塔里与梅纳拉的侍僧们谈话，选择自己修行的方式。"}, [29]={hint="带上地狱犬红宝石到凄凉之地去，用它捕获一只地狱犬的灵魂。成功之后，将地狱犬红宝石和被禁锢的地狱犬灵魂交给贫瘠之地的梅纳拉·沃伦德。", desc="地狱犬碎片，和 地狱火的灵魂 二选一。"}, [30]={hint="带上地狱火绿宝石到凄凉之地去，用它捕获一个地狱火的灵魂。成功之后，将地狱火绿宝石和被禁锢的地狱火灵魂交给贫瘠之地的梅纳拉·沃伦德。", tag="可选", desc="地狱火碎片，和 地狱犬的灵魂 二选一。"}, [31]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", desc="地狱犬碎片，和 地狱火的灵魂 二选一。"}, [32]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", tag="可选", desc="地狱火碎片，和 地狱犬的灵魂 二选一。"}, [33]={npc="塔贝萨", tgt="塔贝萨"}, [34]={npc="塔贝萨", tgt="塔贝萨", tag="有队伍再做、可选"}, [35]={hint="杀死宝珠之魔，然后与塔贝萨谈一谈。", tag="有队伍再做、可选", desc="宝珠之魔是 40 级精英，找队伍再做。"}, [36]={npc="塔贝萨", tgt="塔贝萨", tag="有队伍再做、可选"}, [37]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [38]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", tag="可选"}, [39]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", tag="可选", desc="选地狱犬碎片的做这条。"}, [40]={hint="等待梅纳拉·沃伦德完成达奥拉赫宝珠，然后再与她谈一谈。", tag="可选", desc="选地狱犬碎片的做这条。"}, [41]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", tag="可选", desc="选地狱犬碎片的做这条。"}, [42]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", tag="可选", desc="选地狱火碎片的做这条。"}, [43]={hint="等待梅纳拉·沃伦德完成诺奥拉赫宝珠，然后再与她谈一谈。", tag="可选", desc="选地狱火碎片的做这条。"}, [44]={npc="梅纳拉·沃伦德", tgt="梅纳拉·沃伦德", tag="可选", desc="选地狱火碎片的做这条。"}, [45]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉"}, [46]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="交任务学召唤地狱战马。"}, [47]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="交任务学召唤地狱战马。"}, [48]={to="Stonetalon Peak", toA="{a:467}", desc="已开尼耶尔前哨站就直接飞过去（经塞拉摩），跳过下一步。石爪峰没开就飞阿斯特兰纳，从灰谷南边的山洞进石爪山脉。"}, [49]={text="从石爪峰沿大路往南下山，经过烈日石居时绕开部落营地，从石爪山脉西南边进凄凉之地，尼耶尔前哨站在凄凉之地北边。", tag="还没开这个飞行点，第一次要用跑的"}, [50]={to="Nijel's Point", toA="{a:608}"}, [51]={nodeA="{a:608}", node="Nijel's Point"}, [52]={npc="安东修士", tgt="安东修士"}, [53]={npc="本迪加斯上尉", tgt="本迪加斯上尉", tag="可选", desc="任何氏族的半人马都掉，但这站不顺路打半人马，科尔卡村的怪等级也偏低；想多补经验再做。"}, [54]={hint="消灭凄凉之地任意氏族的半人马，收集5枚雕刻半人马图腾，再交给尼耶尔前哨站的本迪加斯上尉。", tag="可选"}, [55]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [56]={hint="杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。"}, [57]={hint="把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。"}, [58]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [59]={npc="安东修士", tgt="安东修士"}, [60]={npc="安东修士", tgt="安东修士", tag="可选、有队伍再做"}, [61]={npc="本迪加斯上尉", tgt="本迪加斯上尉", tag="可选"}, [62]={hint="为阿拉希高地的维里克·雷锤收集5个扭曲的火焰图腾、5个扭曲的大地图腾、5个扭曲的空气图腾和5个扭曲的水之图腾。", tag="可选", desc="空气图腾在这里的玛洛迪半人马身上；水之图腾在尘泥沼泽北边的黑鳍鱼人、火焰图腾在荒芜之地的石窟穴居人、大地图腾在悲伤沼泽的失落者身上，经过时顺手收。"}}},
