    ["04-44"] = {grind={[1]={mob="野蛮的枭兽", note="辛特兰中部林地，数量多，和枭兽羽毛同一批。"}, [2]={mob="银鬃捕猎者", note="再往东的狼群，分散，可逐只打。"}}, steps={[1]={to="Southshore", toA="{a:271}", desc="南海镇没开就飞米奈希尔港，搭北边码头往奥伯丁的船，在南海镇下船。"}, [2]={npc="虔诚的莱雷恩", tgt="虔诚的莱雷恩", tag="可选"}, [3]={npc="虔诚的莱雷恩", tgt="虔诚的莱雷恩", tag="可选、有队伍再做", desc="在图书馆击败洛克希，在武器库击败赫洛德，在大教堂击败莫格莱尼和怀特迈恩。可以分几次完成。"}, [4]={npc="虔诚的莱雷恩", tgt="虔诚的莱雷恩", tag="可选、材料齐了才做"}, [5]={text="往东北走山路进辛特兰。"}, [6]={npc="弗斯塔德·蛮锤", tgt="弗斯塔德·蛮锤"}, [7]={nodeA="{a:348}", node="Aerie Peak"}, [8]={npc="弗斯塔德·蛮锤", tgt="弗斯塔德·蛮锤"}, [9]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [10]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [11]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [12]={npc="弗拉加尔", tgt="弗拉加尔"}, [13]={npc="弗拉加尔", tgt="弗拉加尔"}, [14]={text="在鹰巢山旅店绑炉石（13.80, 41.60）。", bindA="{a:348}"}, [15]={npc="拉普索迪·铁铲", tgt="拉普索迪·铁铲", desc="去打枭兽的路上；后续要带酒，不接。"}, [16]={hint="为鲁瑟兰村的艾瑞拉斯·琥珀收集15支枭兽羽毛。"}, [17]={hint="检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。"}, [18]={desc="还不到 47 级，就往东打野蛮的枭兽、银鬃捕猎者补到 47 级，顺便收枭兽羽毛。"}, [19]={hint="给鹰巢山的弗拉加尔带去5条巨魔部族项链。"}, [20]={hint="加基森的斯普琳科要你去给她找到一颗紫色水生菇。"}, [21]={hint="杀掉10个绿色淤泥怪和10个玉石软泥怪，然后回到鹰巢山向弗拉加尔报告。"}, [22]={npc="弗拉加尔", tgt="弗拉加尔"}, [23]={npc="弗拉加尔", tgt="弗拉加尔"}, [24]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [25]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [26]={hint="检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。"}, [27]={npc="OOX-09/HL定位器", npcObj=true, tag="掉落才接、可选", desc="右键背包里的 OOX-09/HL定位器接任务。"}, [28]={npc="自动导航机器人OOX-09/HL", tgt="自动导航机器人OOX-09/HL", tag="可选"}, [29]={npc="自动导航机器人OOX-09/HL", tgt="自动导航机器人OOX-09/HL", tag="可选"}, [30]={hint="将OOX-09/HL护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。", tag="可选"}, [31]={hint="将OOX-09/HL护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。", tag="可选", desc="护送失败：在任务日志放弃这个任务，再找机器人重接。"}, [32]={hint="用超级摄影器FX给加莫里塔拍张照片，然后把它交给鲁瑟兰村的达蕾恩·轻风。"}, [33]={hint="藏宝海湾的威士忌斯利姆想要你帮他找回弄丢的紫葡萄酒。"}, [34]={bindA="{a:348}"}, [35]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [36]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [37]={to="Thelsamar", toA="{a:144}"}, [38]={text="在塞尔萨玛旅店绑定炉石（35.40, 48.40）。", bindA="{a:144}"}, [39]={text="往南出洛克莫丹，从这里的山路进荒芜之地。"}, [40]={npc="维里克·雷锤", tgt="维里克·雷锤", tag="有队伍再做、可选", desc="要先做完元素救兵（剃刀沼泽）和风暴、大地与火焰才接得到。"}, [41]={hint="使用扭曲的图腾，终结野猪人的仪式。", tag="有队伍再做、可选", desc="避难谷地飞米奈希尔港，南码头搭船到塞拉摩，飞萨兰纳尔，往东走进千针石林。"}, [42]={npc="维里克·雷锤", tgt="维里克·雷锤", tag="有队伍再做、可选", desc="萨兰纳尔飞塞拉摩，搭船到米奈希尔港，飞避难谷地。"}, [43]={npc="维里克·雷锤", tgt="维里克·雷锤", tag="可选"}, [44]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选"}, [45]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [46]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", desc="要血顶巨魔的獠牙 ×30、活根草 ×8、流放精华 ×1。流放精华要拿燃烧咒符、雷霆咒符、海浪咒符各 8 个到旁边的大锅换。活根草和三种咒符可以在拍卖行买。"}, [47]={hint="把巴斯拉的羊皮纸上列出的东西交给奥特兰克的捕风者巴斯拉。"}, [48]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [49]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [50]={hint="将旋风之心带给捕风者巴斯拉。"}, [51]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [52]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", desc="奖励旋风武器。"}, [53]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", desc="奖励旋风武器。"}}},
    ["04-45"] = {grind={[1]={mob="黑铁工头", note="大熔炉外围的黑铁矮人，等级合适。"}, [2]={mob="黑铁奴隶贩子", note="大熔炉南侧，等级略低，数量分散。"}}, steps={[1]={npc="西格鲁·铁斧", tgt="西格鲁·铁斧", tag="可选", desc="沿途通常会掉炽热魔符；没掉就放弃。"}, [2]={npc="加瑞克", tgt="加瑞克", tag="有队伍再做、可选", desc="要打两只 50 级精英黑龙，没队伍就跳过。"}, [3]={hint="用大地印章激活钻石之柱、欧泊之柱和紫水晶之柱并拿到三颗符石。", tag="之后顺路、有队伍再做、可选"}, [4]={npc="大地封印", npcObj=true, tag="有队伍再做、可选"}, [5]={npc="大地封印", npcObj=true, tag="有队伍再做、可选"}, [6]={npc="加瑞克", tgt="加瑞克", tag="有队伍再做、可选"}, [7]={npc="西格鲁·铁斧", tgt="西格鲁·铁斧", tag="可选"}, [8]={hint="杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。", tag="有队伍再做、可选"}, [9]={text="从荒芜之地往西走，经部落营地卡加斯旁的山路进灼热峡谷，卡加斯要绕开。", tag="还没开这个飞行点，第一次要用跑的"}, [10]={npc="木制厕所", npcObj=true, desc="丝绸可以在拍卖行买，要 15 块。"}, [11]={hint="杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。"}, [12]={text="击杀狂暴的玛尔戈，经验很多。", tag="可选", desc="玛尔戈的角开启通往灼热峡谷的大门钥匙任务线；不想打就跳过，后面相关步骤会自动略过，最后从铁炉堡飞回瑟银哨塔。"}, [13]={npc="玛尔戈的角", npcObj=true, tag="可选、有队伍再做", desc="右键背包里的玛尔戈的角接任务。"}, [14]={npc="木制厕所", npcObj=true}, [15]={npc="木制厕所", npcObj=true, tag="可选", desc="交件要四样：厕所旁的账本、晶网蜘蛛腿 ×20、尘泥沼泽的逾期包裹、悲伤沼泽加奎亚的剑。缺的不用专程去。"}, [16]={hint="把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。", tag="材料齐了才做"}, [17]={npc="杜里奥斯·裂石", tgt="杜里奥斯·裂石", desc="护送杜里奥斯往北；遇伏后在原地捡烧焦的信件交。"}, [18]={npc="烧焦的信件", npcObj=true}, [19]={npc="烧焦的信件", npcObj=true}, [20]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [21]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [22]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [23]={nodeA="{a:1446}", node="Thorium Point"}, [24]={npc="通缉/寻物/招领", npcObj=true, tag="有队伍再做、可选", desc="工头玛托留斯是 50 级精英，没队伍就跳过。"}, [25]={npc="通缉/寻物/招领", npcObj=true}, [26]={npc="通缉/寻物/招领", npcObj=true}, [27]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [28]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳", tag="可选"}, [29]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [30]={npc="大铁匠博恩奈特", tgt="大铁匠博恩奈特"}, [31]={bindA="{a:144}"}, [32]={npc="巡山人贝波蒂", tgt="巡山人贝波蒂", tag="可选"}, [33]={npc="巡山人贝波蒂", tgt="巡山人贝波蒂"}, [34]={to="铁炉堡"}, [35]={npc="维里克·雷锤", tgt="维里克·雷锤", tag="可选"}, [37]={npc="索里奥斯馆长", tgt="索里奥斯馆长"}, [38]={npc="索里奥斯馆长", tgt="索里奥斯馆长"}, [39]={npc="索里奥斯馆长", tgt="索里奥斯馆长", tag="可选"}, [40]={npc="索里奥斯馆长", tgt="索里奥斯馆长"}, [41]={npc="顾问贝尔格拉姆", tgt="顾问贝尔格拉姆", tag="有队伍再做、可选"}, [42]={npc="顾问贝尔格拉姆", tgt="顾问贝尔格拉姆", tag="可选、有队伍再做"}, [43]={to="Thelsamar", toA="{a:144}", tag="可选", desc="有\"馆长的证明！\"才回贝波蒂拿钥匙；没有就跳过，直接从铁炉堡飞回瑟银哨塔。"}, [44]={npc="巡山人贝波蒂", tgt="巡山人贝波蒂", tag="可选"}, [45]={text="用刚拿到的通往灼热峡谷的大门钥匙打开巡山人贝波蒂旁的大门，穿过隧道进灼热峡谷。", tag="可选"}, [46]={to="Thorium Point", toA="{a:1446}", desc="没有通往灼热峡谷的大门钥匙的人从铁炉堡直飞回灼热峡谷；已经穿隧道进来的跳过。"}, [47]={hint="收集4份烈焰之心和4份傀儡之油，然后把这些东西交给威拉罗克·温布雷。"}, [48]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [49]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [50]={hint="找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。"}, [51]={hint="杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。"}, [52]={hint="汉瑟尔·重拳让你杀掉20个重型作战傀儡。"}, [53]={hint="汉瑟尔·重拳要你在灼热峡谷杀死20只灼热熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池附近找到它们。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [54]={text="从东侧有矿工的入口进入时，右转沿下层岩浆旁的通道走到熏火龙洞。"}, [55]={hint="汉瑟尔·重拳让你去杀掉20个熏火龙。"}, [56]={desc="离48级还差经验，可以留在刚才打熏火龙的矿坑，沿清过的通道把普通熏火龙逐只拉过来打。洞里没有安全目标，就原路退出，到大熔炉外围打黑铁工头或奴隶贩子。"}, [57]={hint="那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。", tag="之后顺路、有队伍再做、可选"}, [58]={text="从东侧去图纸时，过桥进大厅后左转。图纸在上层平台工头身后的桌子上。精英守着时可先跳过，有安全空当或队伍再恢复。"}, [59]={hint="在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。", desc="精英工头玛托留斯或黑铁斥候可能守在上层平台。单人先看清桌子附近的情况，安全时再拿图纸。只有悬赏需要击杀工头。"}, [60]={hint="给威拉罗克·温布雷带去8把瑟银匕首。"}, [61]={npc="濒死的考古学家", tgt="濒死的考古学家"}, [62]={npc="濒死的考古学家", tgt="濒死的考古学家", tag="可选"}, [63]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [64]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [65]={hint="到北方去找到被暮光之锤守卫着的神秘的古器。", tag="可选、之后顺路"}, [66]={hint="找到一个拉格纳罗斯符记，把它交给威拉罗克·温布雷。", tag="有队伍再做、可选、之后顺路", desc="符记只有精英掉。"}, [67]={npc="萨麦尔·月棘", tgt="萨麦尔·月棘"}, [68]={npc="萨麦尔·月棘", tgt="萨麦尔·月棘"}, [69]={npc="萨麦尔·月棘", tgt="萨麦尔·月棘", tag="有队伍再做、可选"}, [70]={npc="侦查队长洛洛尔", tgt="侦查队长洛洛尔", tag="有队伍再做、可选"}, [71]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [72]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳", tag="可选"}, [73]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [74]={npc="监工斯克兰格", tgt="监工斯克兰格"}, [75]={npc="监工斯克兰格", tgt="监工斯克兰格"}, [76]={npc="大铁匠博恩奈特", tgt="大铁匠