    ["04-46"] = {grind={[1]={mob="蓝鬃猩猩", note="穆克拉所在的小岛，普通怪，打完王顺手清。"}, [2]={mob="丛林猎豹", note="同一座岛的西侧。"}}, steps={[1]={to="Booty Bay", toA="{a:35}", desc="悲伤沼泽没有联盟飞行点：往西过逆风小径走回夜色镇再飞。"}, [2]={npc="克兰克·菲兹巴布", tgt="克兰克·菲兹巴布"}, [3]={npc="克兰克·菲兹巴布", tgt="克兰克·菲兹巴布"}, [4]={npc="威士忌斯利姆", tgt="威士忌斯利姆"}, [5]={npc="海狼马克基雷", tgt="海狼马克基雷"}, [6]={npc="芬·菲兹拉克", tgt="芬·菲兹拉克", tag="可选"}, [7]={npc="奥格索普·奥布诺提斯", tgt="奥格索普·奥布诺提斯", tag="可选"}, [8]={npc="奥格索普·奥布诺提斯", tgt="奥格索普·奥布诺提斯", tag="可选"}, [9]={npc="奥格索普·奥布诺提斯", tgt="奥格索普·奥布诺提斯", tag="可选"}, [10]={npc="奥格索普·奥布诺提斯", tgt="奥格索普·奥布诺提斯", tag="可选"}, [11]={npc="奥格索普·奥布诺提斯", tgt="奥格索普·奥布诺提斯", tag="可选"}, [12]={npc="仔细折叠的便笺", npcObj=true, desc="右键背包里的仔细折叠的便笺接任务。；之前拿到的折好的纸条现在右键开任务。"}, [13]={npc="普巴尔公主", tgt="普巴尔公主"}, [14]={npc="普巴尔公主", tgt="普巴尔公主", tag="有队伍再做、可选"}, [15]={hint="杀死穆克拉并带着钥匙回去救出普巴尔公主。", tag="有队伍再做、可选"}, [16]={npc="普巴尔公主", tgt="普巴尔公主", tag="有队伍再做、可选"}, [17]={desc="还不到 49 级，就留在岛上打蓝鬃猩猩、丛林猎豹补到 49 级。"}, [18]={hint="找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的心脏交给芬·菲兹拉克。", tag="之后顺路"}, [19]={npc="芬·菲兹拉克", tgt="芬·菲兹拉克", tag="可选"}, [20]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}, [21]={hint="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。"}, [22]={to="Theramore"}, [23]={npc="发霉的卷轴", npcObj=true}, [24]={npc="发霉的卷轴", npcObj=true, tag="可选"}}},
    ["04-47"] = {steps={[1]={to="Gadgetzan", toA="{a:976}", desc="卷轴在尘泥沼泽西南的迅猛龙洞穴，先往东走回塞拉摩（67.48, 51.30）再飞。"}, [2]={npc="克林科·古德斯迪尔", tgt="克林科·古德斯迪尔", tag="材料齐了才做"}, [3]={npc="斯普琳科", tgt="斯普琳科"}, [4]={npc="斯普琳科", tgt="斯普琳科"}, [5]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [6]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [7]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [8]={text="从加基森往北沿大路进千针石林闪光平原。"}, [9]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [10]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [11]={npc="侏儒车队老板", tgt="侏儒车队老板"}, [12]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [13]={npc="奥丹姆石座", npcObj=true}, [14]={npc="诺甘农的石卫兵", tgt="诺甘农的石卫兵"}, [15]={npc="奥丹姆石座", npcObj=true}, [16]={npc="奥丹姆石座", npcObj=true}, [17]={text="往西北走到去安戈洛环形山的山路口。"}}},
    ["04-48"] = {grind={[1]={mob="血瓣花鞭笞者", note="东侧的植物群，刚进环形山时打。"}, [2]={mob="安戈洛猩猩", note="东北猩猩洞外，和猩猩皮同一批。"}, [3]={mob="翼手龙", note="马绍尔营地东边的山壁。"}, [4]={mob="焦油潜伏者", note="营地南边的焦油坑，等级偏高，逐只拉。"}}, steps={[1]={text="从塔纳利斯西边的山路走坡道下安戈洛环形山，托尔瓦·寻路者就在坡道底的入口旁。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="能打高阶怪再做、可选"}, [3]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [4]={npc="破碎的木筏", npcObj=true, desc="收集红、蓝、绿、黄水晶各 7 个，并从迅猛龙身上拿被撕破的日记。"}, [5]={npc="小背包", npcObj=true}, [6]={npc="小背包", npcObj=true}, [7]={hint="找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。"}, [8]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [9]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [10]={hint="将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。"}, [11]={npc="注能水晶鳞片", npcObj=true, tag="可选"}, [12]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选、材料齐了才做"}, [13]={text="先用背包里的注能水晶鳞片接微晶污染，再向托尔瓦交这两个任务。"}, [14]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [15]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选"}, [16]={hint="使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的头颅交给安戈洛环形山入口处的托尔瓦·寻路者。", tag="有队伍再做、可选", desc="这件较难，可留到回安戈洛时再做。"}, [17]={npc="卡尔纳·雷塔维", tgt="卡尔纳·雷塔维"}, [18]={npc="林克", tgt="林克"}, [19]={npc="林克", tgt="林克"}, [20]={nodeA="{a:541}", node="Marshal's Refuge"}, [21]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [22]={npc="霍莱伊·马绍尔", tgt="霍莱伊·马绍尔"}, [23]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [24]={npc="科琳", tgt="科琳", desc="沿路捡四色能量水晶。第一次见科琳时，四色各有七块就当面交，还缺就留到下次。"}, [25]={npc="当心翼手龙", npcObj=true}, [26]={npc="穆尔金", tgt="穆尔金"}, [27]={npc="希兹尔", tgt="希兹尔"}, [28]={hint="将8根恐龙骨头交给安戈洛环形山的斯巴克·尼米尔。"}, [29]={hint="将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。", tag="能打高阶怪再做、可选"}, [30]={desc="还不到 50 级，就留在猩猩洞外打安戈洛猩猩补到 50 级。"}, [31]={hint="从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。"}, [32]={text="拾取东边营地的食物箱。"}, [33]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [34]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [35]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [36]={text="要进虫巢采样：往西南走到洞口再往里走（50.40, 78.80 → 48.70, 85.20）。"}, [37]={hint="使用采集瓶从安戈洛环形山的某个格里什虫巢的孵化室中收集一份巢穴侧壁的样本，在有悬挂着的虫卵的房间里收集样本。"}, [38]={text="把手上的击杀、收集任务做完。"}, [39]={hint="将食物箱和研究设备交给安戈洛环形山的威利德·马绍尔。", desc="食物箱在东边（去猩猩洞、托尔瓦的路上），研究设备在西南（虫巢往翼手龙的路上），两处顺路各捡一个。"}, [40]={hint="为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。"}, [41]={hint="杀掉10只翼手龙和15只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。"}, [42]={npc="希兹尔", tgt="希兹尔"}, [43]={npc="穆尔金", tgt="穆尔金"}, [44]={npc="穆尔金", tgt="穆尔金"}, [45]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [46]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [47]={npc="霍莱伊·马绍尔", tgt="霍莱伊·马绍尔"}, [48]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [49]={npc="被撕破的日记", npcObj=true, tag="可选", desc="打怪捡到被撕破的日记才右键接。"}, [50]={npc="威利德·马绍尔", tgt="威利德·马绍尔", tag="可选"}, [51]={desc="还不到 51 级，就在营地东边打翼手龙，或南边焦油坑打焦油潜伏者补到 51 级。"}, [52]={bind="铁炉堡", desc="如果炉石绑定在铁炉堡，等炉石可用再回城。牧师可找高阶牧师洛汉接\"塞纳里奥议会的求助\"；法师想接\"法师的会见\"可找丁克。"}, [53]={text="要接暴风城的导引才去：在铁炉堡搭矿道地铁到暴风城。", tag="可选"}, [54]={npc="玛吉诺·仲马", tgt="玛吉诺·仲马", tag="可选", desc="暴风城的导引可略过；到艾萨拉仍要先找萨纳斯传送上悬崖。"}, [55]={text="从暴风城飞米奈希尔港，接回路线。", tag="可选"}, [56]={npc="高阶牧师洛汉", tgt="高阶牧师洛汉", tag="可以先在拍卖行买（或请小号寄来）1 份亡灵腐液（之后艾萨拉的亡灵的腐液用）。", desc="到艾萨拉交给奥汀克。"}, [57]={to="Menethil Harbor", toA="{a:150}", desc="在马绍尔营地查看航班，有去奥伯丁或鲁瑟兰村的航班再搭。没有合适航班，可沿东南斜坡回塔纳利斯，到加基森再查看。"}, [58]={to="奥伯丁", from="Menethil Harbor", fromA="{a:150}", desc="这班船中途停南海镇，到奥伯丁再下船。"}, [59]={to="Rut'theran Village", toA="{a:702}", desc="在奥伯丁转往鲁瑟兰村。如果仍在船上，靠岸后下船；有可用航班就飞，否则到北码头（33.3，39.8）坐船。"}, [60]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [61]={npc="达蕾恩·轻风", tgt="达蕾恩·轻风"}, [62]={npc="达蕾恩·轻风", tgt="达蕾恩·轻风"}, [63]={text="走进鲁瑟兰村的传送门到达纳苏斯。", tag="可以先在拍卖行买（或请小号寄来）1 个秘银外壳（之后安戈洛的找回A-Me 01用）。"}, [64]={npc="格拉希娜·灵风", tgt="格拉希娜·灵风"}, [65]={npc="格拉希娜·灵风", tgt="格拉希娜·灵风"}, [66]={npc="阿斯塔利·逐星", tgt="阿斯塔利·逐星", tag="有队伍再做、可选"}, [67]={npc="多利安", tgt="多利安", desc="在达纳苏斯（或铁炉堡、暴风城）接，到艾萨拉交给奥汀克。"}, [68]={text="走进达纳苏斯的传送门回鲁瑟兰村。"}, [69]={to="Astranaar", toA="{a:415}"}, [70]={text="在阿斯特兰纳旅店绑定炉石（37.00, 49.20）。", bindA="{a:415}"}, [71]={npc="萨纳斯", tgt="萨纳斯", tag="可选", desc="有接导引才在这里交。"}, [72]={text="找萨纳斯对话，请他把你传送上悬崖找大法师克希雷姆。"}, [73]={npc="大法师克希雷姆", tgt="大法师克希雷姆"}, [74]={hint="为大法师克希雷姆收集10份闪光尘埃。"}, [75]={npc="大法师克希雷姆", tgt="大法师克希雷姆", desc="尘埃在山下，回去同样找萨纳斯传送上来。"}, [76]={npc="大法师克希雷姆", tgt="大法师克希雷姆"}, [77]={hint="收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。"}, [78]={npc="大法师克希雷姆", tgt="大法师克希雷姆"}, [79]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="有队伍再做、可选", desc="摩弗拉斯在阿塔哈卡神庙。"}, [80]={hint="从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。", tag="有队伍再做、可选", desc="摩弗拉斯在阿塔哈卡神庙。"}, [81]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="有队伍再做、可选", desc="摩弗拉斯在阿塔哈卡神庙。下悬崖用炉石，或找克希雷姆身边的传送选项。"}, [82]={text="回塔伦迪斯营地飞阿斯特兰纳，再沿大路往北进费伍德森林。"}, [83]={npc="奥汀克", tgt="奥汀克"}, [84]={npc="奥汀克", tgt="奥汀克"}, [85]={hint="收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。"}, [86]={npc="奥汀克", tgt="奥汀克"}, [87]={npc="奥汀克", tgt="奥汀克", desc="亡灵腐液 ×1 可以在拍卖行买。"}, [88]={hint="为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。"}, [89]={npc="奥汀克", tgt="奥汀克"}, [90]={npc="奥汀克", tgt="奥汀克", tag="有队伍再做、可选", desc="摩弗拉斯在阿塔哈卡神庙。"}, [91]={text="仍在艾萨拉就回塔伦迪斯营地飞阿斯特兰纳，往北进费伍德森林。已出神庙就直接到费伍德森林的翡翠圣地。"}, [92]={npc="奥汀克", tgt="奥汀克", desc="在达纳苏斯（或铁炉堡、暴风城）接，到艾萨拉交给奥汀克。"}, [93]={npc="奥汀克", tgt="奥汀克"}, [94]={hint="将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。"}, [95]={npc="奥汀克", tgt="奥汀克"}, [96]={npc="奥汀克", tgt="奥汀克"}, [97]={hint="将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。"}, [98]={npc="奥汀克", tgt="奥汀克"}, [99]={npc="奥汀克", tgt="奥汀克", tag="有队伍再做、可选", desc="绿龙在阿塔哈卡神庙。"}, [100]={hint="将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。", tag="有队伍再做、可选", desc="绿龙在阿塔哈卡神庙。"}, [101]={npc="奥汀克", tgt="奥汀克", tag="有队伍再做、可选", desc="绿龙在阿塔哈卡神庙。"}, [102]={text="回塔伦迪斯营地飞阿斯特兰纳，再沿大路往北进费伍德森林。"}, [103]={text="先确认所在位置。如果仍在船上，等船停靠目的港后再下船；在奥伯丁转往鲁瑟兰村，已在鲁瑟兰村岸上就去交任务。"}, [104]={text="去东部接职业任务前，先在马绍尔营地查看前往奥伯丁的航班。没有合适航班，可沿东南斜坡回塔纳利斯，到加基森再查看；抵达奥伯丁后搭直达暴风城的船。"}, [105]={text="从奥伯丁搭直达暴风城的船。若还在船上，靠稳后下船，去暴风城码头（30.5，40.9）等船。"}, [106]={text="从暴风港坐船回奥伯丁。到前往奥伯丁的码头（21.8，56.9）等船，靠岸后继续卡利姆多的路线。"}, [107]={text="先确认所在位置和任务日志空位。如果要去东部接职业任务，请先留一格；若仍在船上，等船停靠目的港后再下船。"}, [108]={text="等船在暴风港靠稳后下船，再到城内找发布职业任务的NPC。如果还在海上，先留在船上。"}, [109]={npc="乔舒修士", tgt="乔舒修士"}, [110]={npc="丁克", tgt="丁克", tag="可选"}, [111]={text="先找铁炉堡的飞行管理员查看前往米奈希尔港的航班。若无法搭乘，可改坐矿道地铁到暴风城，再从暴风港坐船去奥伯丁。"}}},
    ["04-49"] = {grind={[1]={mob="加德纳尔守护者", note="加德纳尔入口一带，普通怪。"}, [2]={mob="加德纳尔祭司", note="和守护者混在一起，施法怪。"}}, steps={[1]={text="从阿斯特兰纳沿大路往北进费伍德森林。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={npc="阿拉珊蒂丝·银空", tgt="阿拉珊蒂丝·银空"}, [3]={npc="格拉兹", tgt="格拉兹"}, [4]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [5]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="有队伍再做、可选、材料齐了才做"}, [6]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [7]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽", tag="可选"}, [8]={hint="格拉兹要你去杀死6个死木战士、6个死木探路者以及6个死木园丁。"}, [9]={npc="格拉兹", tgt="格拉兹"}, [10]={npc="格拉兹", tgt="格拉兹"}, [11]={hint="杀掉11个碧火魔仆、9个碧火巡影者、9个碧火潜行者和萨瓦瑟拉斯。任务完成之后回到费伍德森林的艾瑞丹·蓝风处复命。"}, [12]={hint="到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。"}, [13]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [14]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [15]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [16]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [17]={hint="把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。"}, [18]={desc="在加德纳尔 35, 59 一带打怪。"}, [19]={hint="杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [20]={hint="费伍德森林的艾瑞丹·蓝风要你去杀掉8个碧火唤魔者、8个碧火背叛者、8个碧火欺诈者和萨瓦里克。任务完成之后回到艾瑞丹那里复命。"}, [21]={npc="萨瓦里克长笛", npcObj=true, desc="右键背包里的萨瓦里克长笛接任务。"}, [22]={hint="将萨瓦里克长笛和5个碧火魔符交给费伍德森林南部的艾瑞丹·蓝风。"}, [23]={hint="收集15颗血琥珀，把它们交给费伍德森林的阿拉珊蒂丝·银空。"}, [24]={nodeA="{a:1998}", node="Talonbranch Glade"}, [25]={npc="纳菲恩", tgt="纳菲恩"}, [26]={npc="纳菲恩", tgt="纳菲恩"}, [27]={hint="格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。"}, [28]={npc="纳菲恩", tgt="纳菲恩"}, [29]={text="从这里进木喉要塞的山洞，穿过去就是冬泉谷。"}, [30]={node="月光林地", desc="木喉要塞山洞里有岔路通月光林地，先过去开启飞行点，再回洞里往冬泉谷走。之后海加尔山那段要飞月光林地。"}, [31]={npc="萨尔法", tgt="萨尔法"}, [32]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [33]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [34]={npc="麦吉·贝比罗克", tgt="麦吉·贝比罗克"}, [35]={npc="杰希卡·雷德帕斯", tgt="杰希卡·雷德帕斯"}, [36]={nodeA="{a:2255}", node="Everlook"}, [37]={npc="万能的尼比", tgt="万能的尼比"}, [38]={npc="伊普斯", tgt="伊普斯"}, [39]={npc="伊普斯", tgt="伊普斯", desc="恶魔布 ×1 可以在拍卖行买。"}, [40]={hint="将一块恶魔布交给费伍德森林的伊普斯。"}, [41]={npc="伊普斯", tgt="伊普斯"}, [42]={npc="伊普斯", tgt="伊普斯"}, [43]={hint="将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。"}, [44]={npc="伊普斯", tgt="伊普斯"}, [45]={npc="伊普斯", tgt="伊普斯", tag="有队伍再做、可选"}, [46]={hint="到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。", tag="有队伍再做、可选"}, [47]={npc="伊普斯", tgt="伊普斯", tag="有队伍再做、可选"}, [48]={npc="伊普斯", tgt="伊普斯"}, [49]={hint="费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。"}, [50]={npc="伊普斯", tgt="伊普斯"}, [51]={npc="伊普斯", tgt="伊普斯", desc="克罗苏斯在费伍德森林北方，要组队。"}, [52]={hint="在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。", desc="克罗苏斯在费伍德森林北方，要组队。"}, [53]={npc="万能的尼比", tgt="万能的尼比", desc="克罗苏斯在费伍德森林北方，要组队。"}}},
    ["05-d14"] = {name="阿塔哈卡神庙", entrance="悲伤沼泽 69.50, 52.50（神庙建筑外部路标）", steps={[1]={npc="安吉拉斯·月风", tgt="安吉拉斯·月风", tag="副本前置链"}, [2]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="副本前置链"}, [3]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="副本前置链"}, [4]={hint="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。", tag="副本前置链"}, [5]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="副本前置链"}, [6]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="石环"}, [7]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="石环"}, [8]={npc="叶基亚", tgt="叶基亚", tag="副本前置链"}, [9]={hint="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。", tag="副本前置链", desc="在菲拉斯恐怖之岛海岸击杀谷地尖啸者。每次对尸体使用叶基亚的树枝，再与出现的灵魂交谈，直到任务日志记录了三个。"}, [10]={npc="叶基亚", tgt="叶基亚", tag="副本前置链"}, [11]={npc="叶基亚", tgt="叶基亚", tag="副本前置链"}, [12]={hint="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。", tag="副本前置链"}, [13]={npc="叶基亚", tgt="叶基亚", tag="副本前置链"}, [14]={npc="叶基亚", tgt="叶基亚", tag="副本前置链"}, [15]={hint="将远古之卵交给塔纳利斯的叶基亚。", tag="副本前置链"}, [16]={npc="叶基亚", tgt="叶基亚", tag="副本前置链"}, [17]={npc="叶基亚", tgt="叶基亚", preText="远古之卵"}, [18]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="副本前置链"}, [19]={hint="为大法师克希雷姆收集10份闪光尘埃。", tag="副本前置链"}, [20]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="副本前置链"}, [21]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="副本前置链"}, [22]={hint="收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。", tag="副本前置链"}, [23]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="副本前置链"}, [24]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="可选", desc="摩弗拉斯在阿塔哈卡神庙。"}, [25]={npc="乔舒修士", tgt="乔舒修士", tag="副本前置链"}, [26]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [27]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [28]={hint="收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。", tag="副本前置链"}, [29]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [30]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [31]={hint="为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。", tag="副本前置链"}, [32]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [33]={npc="奥汀克", tgt="奥汀克", tag="可选", desc="摩弗拉斯在阿塔哈卡神庙。"}, [34]={npc="多利安", tgt="多利安", tag="副本前置链"}, [35]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [36]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [37]={hint="将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。", tag="副本前置链"}, [38]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [39]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [40]={hint="将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。", tag="副本前置链"}, [41]={npc="奥汀克", tgt="奥汀克", tag="副本前置链"}, [42]={npc="奥汀克", tgt="奥汀克", tag="可选", desc="绿龙在阿塔哈卡神庙。"}, [43]={text="阿塔哈卡神庙 入口"}, [44]={hint="在悲伤沼泽沉没的神庙中找到哈卡祭坛。", desc="位置：进门走右侧平路下层，在环廊找哈卡祭坛。", spot="进门走右侧平路下层，在环廊找哈卡祭坛。"}, [45]={npc="哈卡祭坛", npcObj=true, spot="环廊下层的哈卡祭坛"}, [46]={hint="到沉没的神庙去，揭开雕像群中隐藏的秘密。", desc="顺序有误会触发陷阱。位置：在下层环廊依序点六像，再到中央打王。顺序：南→北→西南→东南→西北→东北。", spot="在下层环廊依序点六像，再到中央打王。"}, [47]={npc="哈卡神像", npcObj=true, spot="下层中央的哈卡神像"}, [48]={hint="将装满的哈卡之卵交给塔纳利斯的叶基亚。", desc="先全队进房再开事件。从西侧通道去哈卡房。位置：从献祭之穴走西廊进哈卡房，集合后用卵。顺序：西廊通哈卡，东廊通迦玛兰。", spot="从献祭之穴走西廊进哈卡房，集合后用卵。"}, [49]={hint="从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。", tag="可选"}, [50]={hint="前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。", tag="可选"}, [51]={hint="将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。", tag="可选"}, [52]={npc="伊兰尼库斯精华", npcObj=true, tag="可选、有队伍再做", desc="击败最终首领后，右键自己拾取的精华接取任务。"}, [53]={hint="把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。", tag="可选、有队伍再做", spot="把精华放入最终首领旁的精华之泉。"}, [54]={npc="精华之泉", npcObj=true, tag="可选、有队伍再做", spot="把精华放入最终首领旁的精华之泉。"}, [55]={npc="叶基亚", tgt="叶基亚"}, [56]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="可选", desc="摩弗拉斯在阿塔哈卡神庙。下悬崖用炉石，或找克希雷姆身边的传送选项。"}, [57]={npc="奥汀克", tgt="奥汀克", tag="可选", desc="绿龙在阿塔哈卡神庙。"}, [58]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选、材料齐了才做"}}},
    ["04-50"] = {steps={[1]={to="Feathermoon Stronghold", toA="{a:1116}"}, [2]={npc="普拉特·马克格鲁比", tgt="普拉特·马克格鲁比"}, [3]={npc="特洛亚斯·月风", tgt="特洛亚斯·月风"}, [4]={npc="特洛亚斯·月风", tgt="特洛亚斯·月风"}, [5]={npc="格雷甘·山酒", tgt="格雷甘·山酒"}, [6]={hint="去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。", desc="格雷甘给诱饵，拿去引开米布隆、捡灵根草，回来换视灵药剂。"}, [7]={npc="罗克比特", tgt="罗克比特"}, [8]={hint="给特洛亚斯的法杖注入能量，并找到艾奎尼克斯石碑。", desc="后面可以跳上去抄捷径。"}, [9]={npc="艾奎尼克斯石碑", npcObj=true, desc="使用背包里的法杖。"}, [10]={npc="艾奎尼克斯石碑", npcObj=true}, [11]={npc="沙恩·飘叶", tgt="沙恩·飘叶"}, [12]={npc="沙恩·飘叶", tgt="沙恩·飘叶", tag="护送"}, [13]={hint="从箱子里拿取沙恩的铃铛，然后护送沙恩·飘叶回到罗克比特的营地。"}, [14]={npc="罗克比特", tgt="罗克比特"}, [15]={hint="把10块怒痕雪人的毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。"}, [16]={npc="原始雪人毛皮", npcObj=true, tag="可选", desc="打雪人时有掉原始雪人毛皮就右键接。"}, [17]={npc="普拉特·马克格鲁比", tgt="普拉特·马克格鲁比"}, [18]={npc="普拉特·马克格鲁比", tgt="普拉特·马克格鲁比", tag="可选"}, [19]={npc="特洛亚斯·月风", tgt="特洛亚斯·月风"}}},
    ["04-51"] = {grind={[1]={mob="冬泉探路者", note="多诺瓦北边的冬泉熊怪营地，和熊怪任务同一批。"}, [2]={mob="冬泉图腾师", note="同一个营地，施法怪。"}}, steps={[1]={bindA="{a:415}", desc="炉石还在冷却就从羽月要塞飞阿斯特兰纳（经奥伯丁），再往北走进费伍德。"}, [2]={npc="阿拉珊蒂丝·银空", tgt="阿拉珊蒂丝·银空"}, [3]={npc="阿拉珊蒂丝·银空", tgt="阿拉珊蒂丝·银空"}, [4]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [5]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="有队伍再做、可选、材料齐了才做"}, [6]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [7]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [8]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [9]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [10]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽"}, [11]={hint="掉落自：被诅咒的软泥怪、被污染的软泥怪、邪恶的软泥怪", desc="背包要留着塞纳里奥信标才会掉；铁喙猫头鹰在圣地西边，软泥怪在西北的水池。"}, [12]={npc="阿拉珊蒂丝·银空", tgt="阿拉珊蒂丝·银空"}, [13]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="回阿斯特兰纳飞刺枝林地，再往北穿过木喉要塞进冬泉谷。"}, [14]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="到加基森外的墓地喝下视灵药剂，以灵魂状态找加里杨。"}, [15]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [16]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [17]={desc="在冬泉熊怪营地 32, 36 一带打熊怪。"}, [18]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通"}, [19]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通"}, [20]={to="Ratchet", toA="{a:392}", desc="会经塔伦迪斯营地转机。"}, [21]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯"}, [22]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦"}, [23]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦"}, [24]={to="Gadgetzan", toA="{a:976}"}, [25]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [26]={text="喝下视灵药剂后保持死亡状态，以灵魂找任务 NPC。"}, [27]={npc="加里杨", tgt="加里杨"}, [28]={npc="加里杨", tgt="加里杨"}, [29]={text="回尸体复活。"}, [30]={npc="明显的墓碑", npcObj=true}, [31]={npc="明显的墓碑", npcObj=true}, [32]={npc="特兰雷克", tgt="特兰雷克"}, [33]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选"}}},
    ["04-52"] = {name="安戈洛环形山", steps={[1]={to="Marshal's Refuge", toA="{a:541}"}, [2]={npc="林克", tgt="林克"}, [3]={npc="林克", tgt="林克"}, [4]={npc="科琳", tgt="科琳"}, [5]={npc="科琳", tgt="科琳"}, [6]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [7]={npc="霍莱伊·马绍尔", tgt="霍莱伊·马绍尔", tag="可选、If offered", desc="送书任务：NPC 有提供就接，带到海加尔山永恒之巅交。看不到任务就先略过。"}, [8]={hint="帮加基森的特兰雷克收集12块极度粘稠的沥青。"}, [9]={npc="克拉兰克", tgt="克拉兰克"}, [10]={hint="到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。"}, [11]={hint="安戈洛尔环形山的克拉兰克要你去找到火羽山中温度最高的地方。", desc="沿山路登上火羽山测温。如果接了火元素灰烬的任务就沿途收集，测好温度再沿山路去找林格。开始护送后，直接向北回马绍尔营地。"}, [12]={npc="林格", tgt="林格", desc="护送任务：组队时等大家进度一致再接，并关掉自动接交。"}, [13]={npc="林格", tgt="林格"}, [14]={hint="把林格带回马绍尔营地的斯普拉格·弗劳克身边。", tag="护送", desc="带林格走回马绍尔营地。他中途会晕倒，晕倒时对他使用斯普拉格的水壶。"}, [15]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [16]={npc="A-Me 01", tgt="A-Me 01"}, [17]={npc="A-Me 01", tgt="A-Me 01"}, [18]={hint="找到一个秘银外壳，然后回到安戈洛环形山的A-Me 01身边。", desc="秘银外壳先在拍卖场买好，或请工程学玩家做。"}, [19]={npc="A-Me 01", tgt="A-Me 01"}, [20]={hint="把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。"}, [21]={npc="A-Me 01", tgt="A-Me 01"}, [22]={hint="将A-Me 01交给安戈洛环形山的卡尔纳·雷塔维。", tag="护送", desc="护送A-Me 01 走回卡尔纳·雷塔维那里，路上的怪会打它要保护。"}, [23]={npc="卡尔纳·雷塔维", tgt="卡尔纳·雷塔维"}, [24]={hint="收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。", desc="四色水晶散在环形山各处地上，前面没捡够的再补。"}, [25]={npc="科琳", tgt="科琳"}, [26]={npc="科琳", tgt="科琳"}, [27]={npc="科琳", tgt="科琳"}, [28]={npc="科琳", tgt="科琳"}, [29]={hint="在安戈洛尔环形山找到北部水晶塔。"}, [30]={hint="在安戈洛尔环形山找到东部水晶塔。"}, [31]={hint="把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。", tag="可选", desc="在南部虫巢附近找格里什异种蝎或工蝎取信息素，沿途从土堆中收集五份泥土。单人可以挑落单的虫，不必深入寻找虫后。"}, [32]={hint="把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。", tag="可选", desc="在南部虫巢附近找格里什异种蝎或工蝎取信息素，沿途从土堆中收集五份泥土。单人可以挑落单的虫，不必深入寻找虫后。"}, [33]={hint="在安戈洛尔环形山找到西部水晶塔。"}, [34]={npc="克拉兰克", tgt="克拉兰克"}, [35]={npc="克拉兰克", tgt="克拉兰克"}, [36]={npc="科琳", tgt="科琳"}, [37]={npc="科琳", tgt="科琳"}, [38]={npc="科琳", tgt="科琳"}, [39]={npc="科琳", tgt="科琳"}, [40]={npc="科琳", tgt="科琳"}, [41]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [42]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [43]={hint="收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。"}, [44]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [45]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [46]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [47]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="有队伍再做、可选"}, [48]={hint="从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。", tag="有队伍再做、可选"}, [49]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="有队伍再做、可选"}, [50]={text="如果还在北边，而且没有要找托尔瓦办的任务，就到马绍尔营地查看飞行地图，可以选加基森就飞过去。如果要交尤尔查的毛皮，或要做托尔瓦的德鲁伊任务，先到东南找他。在托尔瓦旁边或不能飞时，从东南的坡道进入塔纳利斯，再往东北到加基森。"}, [51]={npc="特兰雷克", tgt="特兰雷克"}, [52]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选"}, [53]={to="Ratchet", toA="{a:392}", desc="会经塞拉摩转机。"}, [54]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯"}, [55]={bindA="{a:415}"}, [56]={to="奥伯丁"}, [57]={text="在奥伯丁旅店找旅店老板莎希因绑定炉石（37.04, 44.13）。", bind="奥伯丁"}, [58]={to="Rut'theran Village", toA="{a:702}"}, [59]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [60]={text="走进鲁瑟兰村的传送门到达纳苏斯。"}, [61]={hint="到达纳苏斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然后回到艾瑞丹那儿。"}, [62]={text="走进达纳苏斯的传送门回鲁瑟兰村。"}, [63]={to="Astranaar", toA="{a:415}"}, [64]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [65]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选、If offered", desc="送信任务：NPC 有提供就接，带到海加尔山交给隐士柯萨拉斯。看不到任务就先略过。"}, [66]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [67]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [68]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [69]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [70]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [71]={hint="为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [72]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风", tag="可选"}, [73]={bind="奥伯丁", desc="冷却就走回阿斯特兰纳飞奥伯丁。"}, [74]={to="Menethil Harbor", toA="{a:150}", from="奥伯丁", desc="在奥伯丁搭乘前往米奈希尔港的船，下一站就是米奈希尔港。"}, [75]={to="铁炉堡"}, [76]={npc="史学家卡尼克", tgt="史学家卡尼克"}, [77]={npc="史学家卡尼克", tgt="史学家卡尼克"}, [78]={npc="资深探险家麦格拉斯", tgt="资深探险家麦格拉斯"}, [79]={npc="资深探险家麦格拉斯", tgt="资深探险家麦格拉斯"}, [80]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯"}, [81]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯"}, [82]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯"}}},
    ["05-d11"] = {name="黑石深渊", entrance="灼热峡谷 34.80, 85.30", pickup="沿主线第二次走完安戈洛后，可以回铁炉堡组队，下一站就是燃烧平原。如果提早在灼热峡谷组到队，也可以从峡谷南端进入黑石山。", pickupS={{"沿主线第二次走完安戈洛后，可以回铁炉堡组队，下一站就是燃烧平原"}, {"如果提早在灼热峡谷组到队，也可以从峡谷南端进入黑石山"}}, tips={{k="動線", text="从铁炉堡能飞就飞瑟银哨塔，从灼热峡谷南端进入黑石山。没有航线就从丹莫罗东侧进入洛克莫丹，往南进入荒芜之地，再向西绕开卡加斯进入灼热峡谷。 → 在冬泉谷组到队可以飞奥伯丁。没有航线就经木喉要塞原路返回费伍德森林，再经灰谷前往黑海岸的奥伯丁。坐船去暴风城，转飞瑟银哨塔。如果没开东部的飞行点，就从暴风城经艾尔文森林到赤脊山，从湖畔镇沿北路进入燃烧平原，再往西进黑石山。 → 要继续走燃烧平原的主线，就从黑石山南门出去，沿大路向东到摩根的岗哨。 → 要回羽月要塞，若炉石绑在阿斯特兰纳且可用就先炉回去。否则从燃烧平原经赤脊山、艾尔文森林到暴风城港，坐船回奥伯丁，再飞往羽月要塞。如果没有航线，就从灰谷经石爪山脉、凄凉之地进入菲拉斯，到西海岸的码头坐船上岛。"}}, steps={[1]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁", desc="在黑石山内以灵魂状态找弗兰克罗恩，接取并交付第一步，然后接取第二步再复活。各地进山方法见本页路线。"}, [2]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁"}, [3]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁"}, [4]={text="黑石深渊 入口"}, [5]={hint="杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。"}, [6]={npc="弗兰克罗恩·铸铁的雕像", npcObj=true, desc="在这里交付黑铁的遗产。继续燃烧平原主线就走黑石山南门；如需返回卡利姆多，按本页路线坐船或使用炉石。"}}},
    ["04-54"] = {steps={[1]={text="已开摩根的岗哨就从铁炉堡直接飞过去。没开就飞湖畔镇，沿大路往北进燃烧平原，摩根的岗哨就在入口旁。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={nodeA="{a:2418}", node="Morgan's Vigil"}, [3]={npc="奥拉留斯", tgt="奥拉留斯"}, [4]={npc="奥拉留斯", tgt="奥拉留斯"}, [5]={npc="赫林迪斯·河角", tgt="赫林迪斯·河角", tag="有队伍再做、可选"}, [6]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [7]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [8]={hint="到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。"}, [9]={hint="把石板拓文交给燃烧平原的麦克斯沃特·尤博格林。"}, [10]={hint="杀掉15个火腹食人魔法师、7个火腹食人魔和7个火腹蛮兵，完成任务之后向奥拉留斯报告。"}, [11]={hint="将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。"}, [12]={hint="杀掉15条黑色小龙、10条黑色龙兽和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。", tag="有队伍再做、可选", desc="黑色龙人和幼龙是 51-53 级精英。"}, [13]={npc="塞勒斯·萨雷芬图斯", tgt="塞勒斯·萨雷芬图斯"}, [14]={npc="塞勒斯·萨雷芬图斯", tgt="塞勒斯·萨雷芬图斯"}, [15]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [16]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [17]={npc="奥拉留斯", tgt="奥拉留斯"}, [18]={npc="奥拉留斯", tgt="奥拉留斯", tag="可选"}, [19]={npc="赫林迪斯·河角", tgt="赫林迪斯·河角", tag="有队伍再做、可选"}, [20]={npc="赫林迪斯·河角", tgt="赫林迪斯·河角"}, [21]={hint="找到戈泰什，他应该在巨槌石西面的某处。杀掉戈泰什并把他的头颅交给燃烧平原的奥拉留斯。", tag="可选"}, [22]={hint="奥拉留斯想要50枚黑石徽章。在燃烧平原的兽人身上应该可以找到那些徽章。"}, [23]={npc="奥拉留斯", tgt="奥拉留斯"}, [24]={npc="奥拉留斯", tgt="奥拉留斯", tag="可选"}, [25]={to="Lakeshire", toA="{a:69}", desc="不做真正的主人就直接飞暴风城，跳过下两步。"}, [26]={npc="所罗门镇长", tgt="所罗门镇长"}, [27]={npc="所罗门镇长", tgt="所罗门镇长"}, [28]={to="Stormwind"}, [29]={npc="武神", tgt="武神", tag="可选"}, [31]={npc="格雷森·沙东布瑞克公爵", tgt="格雷森·沙东布瑞克公爵", desc="到西瘟疫之地冰风岗交。"}, [33]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵"}, [34]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵"}, [35]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵"}, [36]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵"}, [37]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵", tag="可选"}, [38]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [39]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [40]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [41]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [42]={npc="公告员古德曼", tgt="公告员古德曼"}, [43]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [44]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [45]={hint="杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。", tag="可选"}, [46]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [47]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [48]={hint="杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。", tag="可选"}, [49]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [50]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="有队伍再做、可选"}, [51]={hint="将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。", tag="有队伍再做、可选"}, [52]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="有队伍再做、可选"}}},
    ["04-55"] = {steps={[1]={to="Aerie Peak", toA="{a:348}", desc="已开冰风岗就直接飞冰风岗，跳过下一步。飞行地图没有鹰巢山就飞南海镇，照辛特兰那次的路往东跑到鹰巢山。"}, [2]={text="从鹰巢山往北走山路进西瘟疫之地东南角（65.30, 86.80），再沿路往西到冰风岗。", tag="还没开这个飞行点，第一次要用跑的"}, [3]={nodeA="{a:3197}", node="Chillwind Camp"}, [4]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [5]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [6]={hint="收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。"}, [7]={npc="高阶牧师赛尔丹尼斯", tgt="高阶牧师赛尔丹尼斯"}, [8]={npc="高阶牧师赛尔丹尼斯", tgt="高阶牧师赛尔丹尼斯"}, [9]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [10]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特", tag="有队伍再做、可选", desc="交任务取得力量之石。"}, [11]={hint="前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。", tag="有队伍再做、可选", desc="交任务取得力量之石。"}, [12]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特", tag="有队伍再做、可选", desc="交任务取得力量之石。"}, [13]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [14]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [15]={npc="银色黎明军官普尔哈特", tgt="银色黎明军官普尔哈特"}, [16]={npc="银色黎明军官普尔哈特", tgt="银色黎明军官普尔哈特"}, [17]={npc="银色黎明军官普尔哈特", tgt="银色黎明军官普尔哈特"}, [18]={npc="银色黎明军官普尔哈特", tgt="银色黎明军官普尔哈特", desc="送信任务，带到海加尔山入口附近交。"}, [19]={npc="弗林特·沙多摩尔", tgt="弗林特·沙多摩尔", tag="可选"}, [20]={npc="弗林特·沙多摩尔", tgt="弗林特·沙多摩尔", tag="可选"}, [21]={hint="杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。"}, [22]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [23]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [24]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [25]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [26]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [27]={hint="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。"}, [28]={hint="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。"}, [29]={npc="瘟疫之锅", npcObj=true}, [30]={npc="瘟疫之锅", npcObj=true}, [31]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [32]={npc="詹妮丝的包裹", npcObj=true}, [33]={npc="詹妮丝的包裹", npcObj=true}, [34]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [35]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [36]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [37]={hint="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。"}, [38]={npc="瘟疫之锅", npcObj=true}, [39]={npc="瘟疫之锅", npcObj=true}, [40]={npc="达尔松夫人的日记", npcObj=true, desc="大锅旁谷仓里的日记。"}, [41]={hint="完成任务目标。"}, [42]={npc="达尔松夫人的日记", npcObj=true}, [43]={npc="厕所", npcObj=true, desc="日记读完再找游荡的骷髅。开厕所后农夫会出现。"}, [44]={hint="掉落自：游荡的骷髅"}, [45]={npc="厕所", npcObj=true}, [46]={npc="锁住的柜橱", npcObj=true, desc="先清厕所周围，开柜后可立即交件。"}, [47]={hint="掉落自：农夫达尔松"}, [48]={npc="锁住的柜橱", npcObj=true}, [49]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [50]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [51]={npc="纳萨尼尔·杜马", tgt="纳萨尼尔·杜马"}, [52]={hint="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。"}, [53]={npc="瘟疫之锅", npcObj=true}, [54]={npc="瘟疫之锅", npcObj=true}, [55]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [56]={hint="消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [57]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [58]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [59]={hint="消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [60]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [61]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [62]={text="往东南走，从这里的山路进辛特兰。"}, [63]={text="在鹰巢山旅店绑定炉石（13.80, 41.60）。", bindA="{a:348}"}, [64]={npc="科泰罗的宝藏", npcObj=true, tag="可选", desc="宝藏在辛特兰东岸，要横跨整张地图；交完用炉石回去。"}, [65]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="从鹰巢山往北走山路进西瘟疫之地，再往东过索多里尔河进东瘟疫之地，提里奥·弗丁就在入口旁的小屋。"}, [2]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [3]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [4]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [5]={hint="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。"}, [6]={hint="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。"}, [7]={hint="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}, [8]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [9]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [10]={hint="找到帕米拉的洋娃娃。", desc="在达隆郡废屋捡头、左半身、右半身三个部件，右键组合。"}, [11]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [12]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [13]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [14]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵"}, [15]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", tag="可选、有队伍再做"}, [16]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", tag="可选、有队伍再做"}, [17]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅", tag="可选、有队伍再做"}, [18]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩", tag="可选、有队伍再做"}, [19]={node="圣光之愿礼拜堂"}, [20]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [21]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯", tag="可选"}, [22]={npc="护理者奥林", tgt="护理者奥林"}, [23]={hint="释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [24]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [25]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [26]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [27]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [28]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [29]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [30]={hint="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。"}, [31]={hint="将塞达尔的头颅交给圣光之愿礼拜堂的护理者奥林。"}, [32]={npc="破损的卷轴", npcObj=true}, [33]={hint="搜寻东瘟疫之地，寻找\"凋零者\"的线索以及失踪的军情七处密探。如果你找到任何军情七处徽章，就把它们交给冰风岗的弗林特·沙多摩尔。", tag="可选", desc="从三具遗骸各取一枚徽章。集齐后查看任务日志中的侦察目标。如果还未完成，到标记点附近侦察，避开精英。"}, [34]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [35]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [36]={npc="护理者奥林", tgt="护理者奥林"}, [37]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯", tag="可选"}}},
    ["04-53"] = {steps={[1]={to="Southshore", toA="{a:271}", desc="会经冰风岗或鹰巢山转机；飞行地图没有南海镇就照旧飞暴风城，到港口搭船去奥伯丁。"}, [2]={npc="虔诚的莱雷恩", tgt="虔诚的莱雷恩", tag="可选、材料齐了才做"}, [3]={to="奥伯丁", from="Southshore", fromA="{a:271}", desc="从南海镇码头乘船去奥伯丁；改飞暴风城的话在暴风城港口上船。"}, [4]={to="Everlook", toA="{a:2255}"}, [5]={hint="冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。"}, [6]={hint="萨尔法要你去击杀8个冬泉萨满祭司、8个冬泉巢穴守卫，以及8个冬泉巨熊怪。萨尔法就在冬泉谷的木喉要塞入口外。"}, [7]={npc="空的火酒瓶", npcObj=true, tag="掉落才接、可选", desc="冬泉熊怪会掉空的火酒瓶，捡到后右键接任务；还没掉就继续打熊怪。"}, [8]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [9]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="有掉落才做"}, [10]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [11]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [12]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="要探索暗语峡谷，下一站进海加尔山时顺路完成。回冬泉谷去月光林地前再交。"}, [13]={hint="从冬泉谷收集10片月光羽毛，然后将它们带给鲁瑟兰村的艾瑞拉斯·琥珀。"}, [14]={npc="萨尔法", tgt="萨尔法"}, [15]={npc="死木蒸锅", npcObj=true}, [16]={npc="死木蒸锅", npcObj=true}, [17]={to="Rut'theran Village", toA="{a:702}", desc="从死木蒸锅往南走到刺枝林地飞行点（62.49, 24.24）起飞，会经奥伯丁转机。"}, [18]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [19]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [20]={npc="达蕾恩·轻风", tgt="达蕾恩·轻风"}, [21]={to="Everlook", toA="{a:2255}"}, [22]={npc="哈鲁·维格索斯", tgt="哈鲁·维格索斯"}, [23]={npc="哈鲁·维格索斯", tgt="哈鲁·维格索斯", tag="可选", desc="镇内对话任务；后续要打精英巨人，不接。"}, [24]={npc="巫医玛艾里", tgt="巫医玛艾里", tag="可选"}, [25]={npc="乌米", tgt="乌米", desc="从多诺瓦那边回来、往南出发前再打雪人。"}, [26]={npc="维恩德·夜风", tgt="维恩德·夜风"}, [27]={npc="维恩德·夜风", tgt="维恩德·夜风"}, [28]={npc="加隆·石矛", tgt="加隆·石矛"}, [29]={npc="加隆·石矛", tgt="加隆·石矛"}, [30]={npc="加隆·石矛", tgt="加隆·石矛"}, [31]={npc="加隆·石矛", tgt="加隆·石矛"}, [32]={hint="使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。"}, [33]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [34]={hint="为永望镇的乌米收集10张厚雪人毛皮。"}, [35]={npc="乌米", tgt="乌米"}, [36]={npc="乌米", tgt="乌米", tag="可选", desc="角只有洞里的雪人女王和雪人王会掉，掉率低；想多补经验再做。"}, [37]={hint="为永望镇的乌米收集2支完美的雪人角。", tag="可选"}, [38]={npc="乌米", tgt="乌米", tag="可选", desc="后续要跑安戈洛和加基森，不接。"}, [39]={npc="破损的箱子", npcObj=true}, [40]={npc="破损的箱子", npcObj=true}, [41]={npc="加隆的马车", npcObj=true}, [42]={npc="加隆的马车", npcObj=true}, [43]={hint="从雪地中拾起加隆的补给物资，然后寻找盗取加隆所说的护符的枭兽。"}, [44]={npc="兰莎尔拉", tgt="兰莎尔拉"}, [45]={npc="兰莎尔拉", tgt="兰莎尔拉"}, [46]={hint="在兰莎尔拉尝试激活艾露恩祭坛的过程中保护她。然后将你的发现报告给鲁瑟兰村的艾瑞拉斯·琥珀。"}}},
    ["04-57"] = {danger={[1]="刚苏罗克（61 级精英奇美拉）在受污染的木槿花到凯蕾娜工坊一带巡逻（约 x55-62.5、y61.5-72.2），打灌木和回工坊时先看位置。", [2]="『苦痛者』瑟拉史卓斯（57 级精英）在受污染的木槿花一带走动，打灌木时留意。", [3]="骨堆会唤出 58 级精英软泥，没组队别点第二次。"}, grind={[1]={note="邪血伤痕北段，魔拂的任务都在这里打。"}}, supply={[1]={}}, steps={[1]={text="从兰莎尔拉往南进暗语峡谷（59.82, 74.25），沿峡谷往西走到底就进海加尔山。峡谷口有冰霜巨人精英，峡谷里有恶魔精英，贴着路走别停。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={hint="根据多诺瓦·雪山的指示行动，然后回到她那里报告。", desc="进海加尔山走峡谷就会完成，不用另外绕。任务日志显示完成就算数。"}, [3]={text="进海加尔山东南角，沿路往西走。"}, [4]={npc="昆图斯·温沃斯", tgt="昆图斯·温沃斯"}, [5]={npc="昆图斯·温沃斯", tgt="昆图斯·温沃斯"}, [6]={npc="松动的齿轮", npcObj=true, desc="路旁地上的齿轮，右键捡起来接任务。"}, [7]={npc="凯萨拉斯", tgt="凯萨拉斯", tag="可选", desc="先前在费伍德森林有接这件才交。"}, [8]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [9]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [10]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [11]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [12]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [13]={hint="拯救12个海加尔猫头鹰蛋，并把它们带给凯萨拉斯。"}, [14]={hint="为凯萨拉斯收集10颗未受污染的种子。"}, [15]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [16]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [17]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [18]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [19]={hint="从纯净的海加尔雄鹿身上收集2块海加尔鹿肉排，并收集6个血色飞镖块茎，用来制作隐士的炖肉。"}, [20]={hint="在毁坏的弩车、毁坏的投石车和毁坏的飞行器附近种下附魔种子。", desc="弩砲、投石车、飞行器三种残骸各算一项，三种都要种到。在隐士洞外的山坡找。"}, [21]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [22]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [23]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [24]={hint="将遗骸埋葬在凯萨拉斯的神龛。"}, [25]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [26]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [27]={nodeA="{a:16853}", node="Tainted Foothills", desc="沿路往西走，飞行点在古树哨站旁。"}, [28]={npc="梣木", tgt="梣木"}, [29]={npc="紫兰", tgt="紫兰"}, [30]={npc="紫兰", tgt="紫兰"}, [31]={npc="塞兰", tgt="塞兰", tag="有队伍再做、可选", desc="目标是 57 级精英，单人打不过就别接。"}, [32]={hint="在海加尔山山麓附近收集6份纯净的土壤。"}, [33]={npc="凯莱娜·春语", tgt="凯莱娜·春语"}, [34]={npc="凯莱娜·春语", tgt="凯莱娜·春语"}, [35]={npc="凯莱娜·春语", tgt="凯莱娜·春语", desc="之后去永望镇时找娜米拿零件。"}, [36]={hint="在污染山麓的工坊里，为凯莱娜·春语摧毁15株腐化的灌木丛。", desc="同一批木槿花也掉树叶止血的叶片，两件一起打。送木箱时回工坊交。"}, [37]={hint="在海加尔山麓被腐化的灌木丛中采集12片翠绿的叶子。"}, [38]={hint="找到并摧毁苦涩的塞拉斯图斯，将它折断的叶片带回给塞莱恩。", tag="有队伍再做、可选"}, [39]={npc="塞兰", tgt="塞兰", tag="有队伍再做、可选"}, [40]={npc="紫兰", tgt="紫兰"}, [41]={n