    ["04-60"] = {danger={[1]="刚苏罗克（61 级精英奇美拉）在凯蕾娜工坊南边山脊走动。", [2]="马佐苟尔（60 级精英）在达尔苟废墟南边巡逻，打猎犬时绕开。", [3]="维汉·爪握（60 级精英）守在诺达希尔小屋，做教徒任务别靠太近。"}, grind={[1]={mob="地狱卫士斥候", note="达尔苟废墟南半部，顺收被遗弃的补给和部落残骸材料。"}, [2]={note="永恒之巅东侧的教徒营地，山顶任务都在这里打。"}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="沿路回东边。"}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="伊莱娜·月语", tgt="伊莱娜·月语"}, [4]={npc="枯须", tgt="枯须"}, [5]={npc="亚史罗", tgt="亚史罗"}, [6]={hint="点燃达尔苟的两堆篝火，然后回到亚史罗身边。"}, [7]={text="点完东南边那处营火，继续往东南走到瑞纳拉德，先交聰明的生物、接骨灰和狐狸任务，回头再一次清达尔苟废墟。"}, [8]={npc="雷纳拉德", tgt="雷纳拉德"}, [9]={npc="雷纳拉德", tgt="雷纳拉德"}, [10]={npc="雷纳拉德", tgt="雷纳拉德"}, [11]={hint="收集8份被遗弃的补给品。", desc="用接任务拿到的狐狸毛（Tuft of Fox Fur）引开恶魔，再捡 8 份被遗弃的补给。补给不在瑞纳拉德身边。"}, [12]={hint="在部落基地的遗迹中翻捡，将5根磨损的电线、5块废金属和5块钙化的粪便带给凯莱娜。"}, [13]={hint="为伊莱娜·月语取回6份短暂精华。"}, [14]={hint="在达尔苟消灭12名恶魔卫士哨兵。"}, [15]={hint="从海加尔山的达尔苟废墟中取回一小撮阿兹加洛的灰烬。"}, [16]={hint="进入达尔苟，找到一个视野开阔的制高点，并向约翰报告详情。"}, [17]={npc="亚史罗", tgt="亚史罗", desc="清完达尔苟废墟回亚希罗这里交。"}, [18]={npc="亚史罗", tgt="亚史罗", tag="可选"}, [19]={hint="与亚史罗一起杀出达尔苟。", tag="有队伍再做、可选", desc="跟着亚希罗清路，最后打倒末日守卫 Xarkul（Doomguard Xarkul）才算完成。"}, [20]={npc="亚史罗", tgt="亚史罗", tag="可选", desc="在事件结束的地方找亚希罗交，不一定回到起点。"}, [21]={npc="伊莱娜·月语", tgt="伊莱娜·月语"}, [22]={npc="伊莱娜·月语", tgt="伊莱娜·月语", tag="有队伍再做、可选", desc="两个目标都是 60 级精英恶魔；没组队就跳过，后续会自动略过。"}, [23]={hint="对贝斯拉泽尔和玛佐戈尔使用无尽影响之眼吸取他们的力量，然后给予他们致命一击。", tag="有队伍再做、可选"}, [24]={npc="伊莱娜·月语", tgt="伊莱娜·月语", tag="有队伍再做、可选"}, [25]={npc="伊莱娜·月语", tgt="伊莱娜·月语"}, [26]={npc="枯须", tgt="枯须"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="雷纳拉德", tgt="雷纳拉德", desc="往东南走。"}, [29]={nodeA="{a:16849}", node="Summit of Eternity", desc="从瑞纳拉德往东上山一小段，开启菲伊伦·埃尔萨斯飞行点。先把带上山的几件交掉，减轻任务日志。"}, [30]={npc="马恩·尤霍恩", tgt="马恩·尤霍恩"}, [31]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃", tag="可选", desc="先前在安戈洛环形山有接这件才交。"}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="塞贝利亚", tgt="塞贝利亚", desc="信件包裹等一下在永望镇交，接着做邮件连锁。"}, [34]={npc="凯莱娜·春语", tgt="凯莱娜·春语", desc="从永恒之巅往西下山经瑞纳拉德，再往南到工坊。山路走不通就飞污染山麓再往北骑。"}, [35]={npc="凯莱娜·春语", tgt="凯莱娜·春语"}, [36]={hint="转动凯莱娜投刃车两侧的齿轮，并接好电池端子。"}, [37]={npc="凯莱娜·春语", tgt="凯莱娜·春语"}, [38]={npc="凯莱娜·春语", tgt="凯莱娜·春语", tag="有队伍再做、可选", desc="引来的刚苏罗克是 61 级精英奇美拉。"}, [39]={hint="前往凯莱娜工坊南边的山脊，设法制造巨响引开注意，将奇美拉甘苏罗克引到可以攻击的范围内。", tag="有队伍再做、可选", desc="在工坊南边的懸崖找鼓互动，把奇美拉引进旋刃投擲器射程，由 NPC 操作投擲器打，别拉去远处硬打。"}, [40]={npc="凯莱娜·春语", tgt="凯莱娜·春语", tag="有队伍再做、可选"}, [41]={npc="菲比·高羽", tgt="菲比·高羽", desc="从工坊往西南走一小段到艾维娜圣殿。"}, [42]={npc="凯萨拉斯", tgt="凯萨拉斯", desc="从圣坛往东南骑回隐士洞。"}, [43]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [44]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [45]={npc="凯萨拉斯", tgt="凯萨拉斯"}, [46]={to="Everlook", toA="{a:2255}", desc="从隐士洞往西骑到污染山麓飞行点起飞。"}, [47]={npc="旅店老板维兹奇", tgt="旅店老板维兹奇"}, [48]={npc="旅店老板维兹奇", tgt="旅店老板维兹奇"}, [49]={hint="在永望镇北边的山丘中寻找4封丢失的信件，将其带给旅店老板维兹奇。", desc="邮件散在永望镇外的山丘上，照任务日志的提示找；找不到可先略过。"}, [50]={npc="旅店老板维兹奇", tgt="旅店老板维兹奇"}, [51]={npc="旅店老板维兹奇", tgt="旅店老板维兹奇", desc="邮件带回海加尔山顶交。"}, [52]={to="Summit of Eternity", toA="{a:16849}", desc="会经污染山麓转机。"}, [53]={npc="塞贝利亚", tgt="塞贝利亚"}, [54]={npc="马恩·尤霍恩", tgt="马恩·尤霍恩"}, [55]={npc="托隆·石蹄", tgt="托隆·石蹄"}, [56]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [57]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [58]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [59]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [61]={hint="在海加尔山顶的森林中寻找荆棘种子，将其带给蒂亚拉·白鬃。"}, [62]={hint="对永恒之巅的10名黑棘契约成员使用山岳法杖，驱散他们的结界后再将其消灭。", desc="同一批教徒也算终结狂热和扭曲的工具，先用法杖再杀，三件一起做。"}, [63]={hint="消灭10个黑棘专家和10个狂野印记教徒。"}, [64]={hint="从黑棘教徒身上夺取一把邪恶仪式克里斯匕首和一根退缩的瘤树皮法杖。"}, [65]={hint="为马恩收集5根大角鹰兽的羽毛和3根油滑的奇美拉毛发"}, [66]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [67]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [68]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [69]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [70]={hint="在忠诚派德鲁伊营地的旅店、储物塔和树丛附近种下荆棘种子。"}, [71]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [72]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [73]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="接完先去玛恩那里交净化之风、接阿克蒙德之赦，两件同一趟去做。"}, [74]={npc="马恩·尤霍恩", tgt="马恩·尤霍恩"}, [75]={npc="马恩·尤霍恩", tgt="马恩·尤霍恩"}, [76]={hint="重新激活黑棘教徒周围北、西、南三面的哨兵石。", desc="北、西、南三块石头各算一项，三块都要去。"}, [77]={hint="使用附魔的树枝，在诺达希尔周围释放5只小精灵。", desc="解放树根下原本就在的小精灵，不是在空地用道具召出来。和阿克蒙德之赦同一趟做。"}, [78]={hint="带上马恩的香，让烟雾护佑阿克蒙德遗骸周围的空气。"}, [79]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [80]={npc="蒂亚拉·白鬃", tgt="蒂亚拉·白鬃"}, [81]={npc="马恩·尤霍恩", tgt="马恩·尤霍恩"}, [82]={npc="托隆·石蹄", tgt="托隆·石蹄"}, [83]={to="Rut'theran Village", toA="{a:702}", desc="会经污染山麓、永望镇转机。"}, [84]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [85]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [86]={text="走进鲁瑟兰村的传送门到达纳苏斯。"}, [87]={npc="大德鲁伊范达尔·鹿盔", tgt="大德鲁伊范达尔·鹿盔"}, [88]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者"}}},
    ["04-59"] = {name="西瘟疫之地", steps={[1]={bindA="{a:348}", desc="仍绑鹰巢山且炉石可用才炉石。否则走船线备案：走传送门回鲁瑟兰村，飞奥伯丁，乘船先到米奈希尔港，再循北线到南海镇下船，再飞冰风岗。"}, [2]={to="Chillwind Camp", toA="{a:3197}", desc="已到冰风岗就跳过。飞行地图没有冰风岗就从鹰巢山往北走山路进西瘟疫之地，再往西跑到冰风岗。"}, [3]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [4]={npc="弗林特·沙多摩尔", tgt="弗林特·沙多摩尔", tag="可选"}, [5]={npc="弗林特·沙多摩尔", tgt="弗林特·沙多摩尔", tag="可选"}, [6]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [7]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [8]={npc="化学家阿尔比顿", tgt="化学家阿尔比顿"}, [9]={npc="化学家阿尔比顿", tgt="化学家阿尔比顿", desc="接了才开始掉骷髅碎片，在悔恨岭和安多哈尔打骷髅时顺便收。"}, [10]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [11]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [12]={hint="把约瑟夫的结婚戒指交给安多哈尔的克罗米。"}, [13]={hint="将15块骷髅碎片交给西瘟疫之地冰风岗的化学家阿尔比顿。"}, [14]={npc="克罗米", tgt="克罗米"}, [15]={npc="克罗米", tgt="克罗米"}, [16]={npc="克罗米", tgt="克罗米"}, [17]={hint="把《达隆郡的历史》交给安多哈尔的克罗米。"}, [18]={hint="在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。"}, [19]={npc="克罗米", tgt="克罗米"}, [20]={npc="克罗米", tgt="克罗米"}, [21]={npc="克罗米", tgt="克罗米"}, [22]={hint="在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。"}, [23]={npc="克罗米", tgt="克罗米"}, [24]={npc="克罗米", tgt="克罗米"}, [25]={to="圣光之愿礼拜堂", desc="安多哈尔没有飞行点，先往南走回冰风岗再飞。"}, [26]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", tag="可选、有队伍再做"}, [27]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [28]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯", tag="可选"}, [29]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [30]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", tag="可选、有队伍再做"}, [31]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", tag="可选、有队伍再做", desc="等队伍下次走亡灵区时再做。"}, [32]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅", tag="可选、有队伍再做"}, [33]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩", tag="可选、有队伍再做"}, [34]={hint="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。"}, [35]={hint="杀了渗透者哈米亚，用他的钥匙开启墓室后的一堆泥土。"}, [36]={npc="奥萝拉", tgt="奥萝拉"}, [37]={hint="在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到西瘟疫之地的冰风岗去找纳萨尼尔·杜马。"}, [38]={hint="将霍古斯的颅骨和马杜克的破碎之剑交给圣光之愿礼拜堂的卡林·雷德帕斯。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [39]={npc="一堆泥土", npcObj=true}, [40]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [41]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [42]={hint="把达维的圣契和雷德帕斯之盾交给卡林·雷德帕斯。"}, [43]={hint="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。"}, [44]={npc="瘟疫之锅", npcObj=true}, [45]={npc="瘟疫之锅", npcObj=true}, [46]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾"}, [47]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [48]={npc="化学家阿尔比顿", tgt="化学家阿尔比顿", desc="后续要进通灵学院，不接。"}, [49]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [50]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [51]={npc="纳萨尼尔·杜马", tgt="纳萨尼尔·杜马"}, [52]={npc="纳萨尼尔·杜马", tgt="纳萨尼尔·杜马"}, [53]={npc="白蚁桶", npcObj=true}, [54]={npc="白蚁桶", npcObj=true}, [55]={hint="使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向西瘟疫之地冰风岗的纳萨尼尔·杜马报告。"}, [56]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [57]={hint="杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。"}, [58]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [59]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [60]={hint="杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。"}, [61]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [62]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [63]={hint="进入壁炉谷并找一处高地，你可以在那里观察整个城镇并估算血色十字军的兵力，然后向西瘟疫之地的科尔斯塔·迪普沙东回报。", desc="坐标是大致位置。入口和塔旁有血色十字军守卫，一次只拉一只。"}, [64]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [65]={npc="纳萨尼尔·杜马", tgt="纳萨尼尔·杜马"}, [66]={to="圣光之愿礼拜堂", desc="人就在冰风岗，直接找飞行管理员。"}, [67]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯", tag="可选"}, [68]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [69]={to="铁炉堡"}, [70]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯"}, [71]={to="Stormwind"}, [72]={npc="皇家代理人巴瑟罗尔", tgt="皇家代理人巴瑟罗尔"}, [73]={npc="皇家代理人巴瑟罗尔", tgt="皇家代理人巴瑟罗尔"}, [74]={npc="艾玛", tgt="艾玛"}, [75]={to="Lakeshire", toA="{a:69}", tag="可选", desc="身上有真正的主人才去湖畔镇；没有就从暴风城直飞摩根的岗哨。"}, [76]={npc="所罗门镇长", tgt="所罗门镇长"}, [77]={npc="所罗门镇长", tgt="所罗门镇长"}, [78]={to="Morgan's Vigil", toA="{a:2418}"}, [79]={npc="麦克斯韦尔元帅", tgt="麦克斯韦尔元帅"}, [80]={npc="麦克斯韦尔元帅", tgt="麦克斯韦尔元帅"}, [81]={npc="奥拉留斯", tgt="奥拉留斯", tag="可选"}, [82]={hint="和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。"}, [83]={hint="把戈泰什的头颅放在巨槌石的山顶上。找一块软土堆把串着头颅的长矛插上去就可以了。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [84]={npc="麦克斯韦尔元帅", tgt="麦克斯韦尔元帅"}, [85]={npc="奥拉留斯", tgt="奥拉留斯", tag="可选"}, [86]={text="还没到 60 级就打一趟黑石深渊；还不够再刷斯坦索姆或通灵学院。"}}},
    ["05-d13"] = {name="斯坦索姆", entrance="东瘟疫之地 26.52, 10.36（血色正门；亡灵区侧门在 43.50, 19.40）", steps={[1]={text="如果要找西瘟疫之地凯尔达隆的画家接\"爱与家庭\"，可以先飞冰风岗。已经接了画作任务，或只需要礼拜堂任务，就直接与队友会合。"}, [2]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [3]={hint="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。", tag="副本前置链"}, [4]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [5]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [6]={hint="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。", tag="副本前置链"}, [7]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [8]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [9]={hint="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。", tag="副本前置链"}, [10]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [11]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [12]={hint="听听提里奥·弗丁要说什么。", tag="副本前置链"}, [13]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [14]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [15]={hint="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。", tag="副本前置链"}, [16]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [17]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [18]={hint="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。", tag="副本前置链"}, [19]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [20]={npc="提里奥·弗丁", tgt="提里奥·弗丁", tag="副本前置链"}, [21]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾", tag="副本前置链"}, [22]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾"}, [23]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", tag="可选、有队伍再做"}, [24]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", tag="可选、有队伍再做"}, [25]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅", tag="可选、有队伍再做"}, [26]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩", tag="可选、有队伍再做"}, [27]={text="从圣光之愿礼拜堂跟队前往斯坦索姆。入口标记是通往市场和血色堡垒的血色区正门。只打亡灵区的话，和能开侧门的队友在东边的侧门会合。"}, [28]={text="斯坦索姆 入口"}, [29]={hint="到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。", tag="可选、有队伍再做", spot="沿两翼的街道查看补给箱，给自己留五瓶斯坦索姆圣水交任务；用掉的要重新收齐。"}, [30]={hint="从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……", tag="可选、有队伍再做", spot="随队在两翼沿路拾取瘟疫肉块，不够就留到下次，集齐二十个再回礼拜堂。"}, [31]={hint="找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。", tag="可选、有队伍再做", spot="从血色区正门进入市场，打开烟草店的箱子，引出并击败艾兹拉·格里姆，拾取一盒特级烟草。只走亡灵侧门的队伍可以下次再做。"}, [32]={hint="到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到\"爱与家庭\"这幅画，它被隐藏在另一幅描绘两个月亮的画之后。", spot="先击败加尔福特。请队友确认，需要「爱与家庭」的人都已取走双月画后面的画，再烧毁档案。如果没人需要取画，就可以直接烧毁档案。"}, [33]={hint="在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。", tag="可选、有队伍再做", spot="先击败加尔福特。请队友确认，需要「爱与家庭」的人都已取走双月画后面的画，再烧毁档案。如果没人需要取画，就可以直接烧毁档案。"}, [34]={npc="巴纳扎尔的头颅", npcObj=true, tag="可选、有队伍再做", desc="交完档案管理员后，右键点击自己从巴纳扎尔拾取的头颅来接取任务。"}, [35]={hint="到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。", tag="可选、有队伍再做", spot="逐座搜索亡灵区的三座通灵塔，找到资料小箱后亲自拾取。"}, [36]={hint="到斯坦索姆去杀掉瑞文戴尔男爵，把他的头颅交给尼古拉斯·瑟伦霍夫公爵。", tag="可选、有队伍再做", spot="亡灵区经屠宰场，击败瑞文戴尔男爵后亲自拾取头颅。"}, [37]={hint="对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！", tag="可选、有队伍再做", spot="沿斯坦索姆街道找鬼魂居民，先使用埃根的冲击器，再对现身的灵魂用一次，一共解放十五个。"}, [38]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥·弗丁在东瘟疫之地西边河岸旁的小屋。"}, [39]={text="返回圣光之愿礼拜堂。如果你带着「爱与家庭」的画，先去东瘟疫之地西边的河岸交给提里奥，再回礼拜堂。"}, [40]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", tag="可选、有队伍再做"}, [41]={npc="巴纳扎尔的头颅", npcObj=true, tag="可选、有队伍再做", desc="交完档案管理员后，右键点击自己从巴纳扎尔拾取的头颅来接取任务。"}, [42]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", tag="可选、有队伍再做"}, [43]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", tag="可选、有队伍再做", desc="等队伍下次走亡灵区时再做。"}, [44]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", tag="可选、有队伍再做"}, [45]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", tag="可选、有队伍再做"}, [46]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", tag="可选、有队伍再做", desc="等队伍下次走亡灵区时再做。"}, [47]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", tag="可选、有队伍再做"}, [48]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅", tag="可选、有队伍再做"}, [49]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩", tag="可选、有队伍再做"}, [50]={npc="埃根", tgt="埃根", tag="可选、有队伍再做"}, [51]={to="铁炉堡"}}},
    ["05-d12"] = {name="黑石深渊", entrance="灼热峡谷 34.80, 85.30", pickup="在铁炉堡交完索瑞森废墟就接卡兰·巨锤；燃烧平原的几件在摩根的岗哨一带接。", pickupS={{"在铁炉堡交完索瑞森废墟就接卡兰·巨锤"}, {"燃烧平原的几件在摩根的岗哨一带接"}}, steps={[1]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯", tag="副本前置链"}, [2]={hint="听皇家历史学家阿克瑟努斯讲述索瑞森的历史。", tag="副本前置链"}, [3]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯", tag="副本前置链"}, [4]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯", tag="副本前置链"}, [5]={hint="到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。", tag="副本前置链"}, [6]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯", tag="副本前置链"}, [7]={npc="国王麦格尼·铜须", tgt="国王麦格尼·铜须", desc="前置是索瑞森废墟，「西瘟疫之地」在铁炉堡交完再接。"}, [8]={npc="拉格纳·雷酒", tgt="拉格纳·雷酒", tag="可选", desc="在诅咒之地接到才交。"}, [9]={npc="拉格纳·雷酒", tgt="拉格纳·雷酒", tag="可选", desc="卡拉诺斯不顺路，不绕就略过。"}, [10]={npc="奥拉留斯", tgt="奥拉留斯"}, [11]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [12]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [13]={hint="听威拉罗克·温布雷讲述他的故事。", tag="副本前置链"}, [14]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [15]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [16]={hint="收集4份烈焰之心和4份傀儡之油，然后把这些东西交给威拉罗克·温布雷。", tag="副本前置链"}, [17]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [18]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [19]={hint="给威拉罗克·温布雷带去8把瑟银匕首。", tag="副本前置链"}, [20]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [21]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [22]={hint="找到一个拉格纳罗斯符记，把它交给威拉罗克·温布雷。", tag="副本前置链"}, [23]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [24]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [25]={hint="等待威拉罗克·温布雷完成惩戒火炬。", tag="副本前置链"}, [26]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [27]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [28]={npc="惩戒火炬", npcObj=true, tag="副本前置链"}, [29]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="副本前置链"}, [30]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="副本前置链"}, [31]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="副本前置链"}, [32]={hint="使用惩戒火炬点燃北部、南部、东部和西部的哨塔。", tag="副本前置链"}, [33]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="副本前置链"}, [34]={npc="黑龙的财宝", npcObj=true, tag="副本前置链"}, [35]={npc="黑龙的财宝", npcObj=true, tag="副本前置链"}, [36]